interface FaqItem {
  q: string;
  a: string;
}
interface FaqCategory {
  title: string;
  icon: React.ElementType;
  color: string;
  items: FaqItem[];
}

const FAQ: FaqCategory[] = [
  {
    title: "Getting Started",
    icon: BookOpen,
    color: "bg-brand/10 text-brand border-brand/20",
    items: [
      { q: "How do I set up my farm on BDE Farm Trac?", a: "After registering, you are taken through a four-step setup wizard automatically. Step 1 captures your business or trading name, contact email, phone, and address. Step 2 covers your farm — name, CPH number (County Parish Holding), postcode, and the farm sectors that apply to your holding (arable, beef cattle, sheep, dairy, pigs, poultry, eggs, goats, equine, fresh produce, or viticulture — tick as many as apply). Step 3 lets you choose which modules to add alongside the required Red Tractor Compliance module. Step 4 is a review screen where you can subscribe directly or go straight to the dashboard to explore first. You can add additional farm holdings to your account at any time from Settings — each holding has its own fields, staff, and records — and you switch between them using the farm selector at the top of the sidebar." },
      { q: "Can I use BDE Farm Trac for more than one farm or holding?", a: "Yes. BDE Farm Trac supports multi-farm accounts. Each farm holding is managed independently — with its own fields, livestock, staff, and compliance records — but you can switch between them instantly from one login. Pricing is per holding per month." },
      { q: "Is my data backed up automatically?", a: "Yes. All data is stored on Barnett Davies Enterprises' cloud infrastructure with automatic daily backups. You do not need to export or manage backups yourself. Records are retained in line with Red Tractor's five-year document retention guidance." },
      { q: "Does BDE Farm Trac work on mobile?", a: "Yes. The BDE Farm Trac mobile app is available for iOS and Android and is designed for field use — spray records, livestock events, fuel drawdowns, visitor sign-in with digital signature, QR scanning, GPS location capture, and photo evidence attachment all work fully offline and sync automatically when connectivity is restored." },
      { q: "Can I attach photos and documents to farm records?", a: "Yes — photo and document attachment is available across the platform on both the mobile app and the dashboard. On mobile, a camera button or attach button appears on record screens including livestock events (vet visits, medicine treatments, mortality, lambing and calving logs, prescriptions), equipment defect reports and maintenance entries, spray application records, visitor log entries, COSHH assessments (Safety Data Sheet photo), biosecurity incidents, and fly-tipping and encampment reports — tap it to take a photo or pick an image from your gallery. On the dashboard, an Attachments panel on supported record screens lets you upload PDFs, images, or Word documents from your computer — including visitor log records, pest control records, COSHH assessments, and cleaning & disinfection records in the Biosecurity module. All attachments are stored in cloud storage and linked permanently to the record, giving you a complete photographic and documentary evidence trail that is accessible instantly during a Red Tractor assessor visit." },
      { q: "Which modules do I need for Red Tractor compliance?", a: "For combinable crops, you will typically need Crop Management (spray records, field journal, variety and seed logs), Soil Management (NMP, NVZ, soil sampling), and Finance & Business (purchase and sales records). Biosecurity and Staff & Training are required for livestock standards. The Pricing page has an interactive module selector to help you choose." },
    ],
  },
  {
    title: "Organic Compliance",
    icon: Sprout,
    color: "bg-green-50 text-green-700 border-green-100",
    items: [
      { q: "Does BDE Farm Trac replace my Soil Association or OF&G portal?", a: "No — and it is not designed to. The Organic Compliance module is a complementary record system. Your official organic certification is managed directly with your certifier (Soil Association, OF&G, Biodynamic Association, etc.). BDE Farm Trac holds a reference copy of your certification details, field status, inspection visits, and restricted input records alongside your other operational records, so everything is in one place for audit purposes." },
      { q: "What is the two-year conversion progress tracker?", a: "For fields recorded as 'In Conversion', BDE Farm Trac automatically calculates how far through the statutory two-year conversion period the land is, displayed as a visual progress bar. It also shows the expected certification date based on your recorded conversion start date." },
      { q: "What counts as a restricted input?", a: "A restricted input is any product not normally permitted under organic standards (such as a synthetic fertiliser or conventional pesticide) used under exceptional circumstances — for example, where no permitted alternative is available and the certifier has been consulted. You must log the product, your written justification, any certifier approval reference, and whether the certifier has been notified. Always consult your certifier before use." },
      { q: "Can I print an organic inspection register for my assessor?", a: "Yes. The Inspections tab in the Organic Compliance module includes a Print Register button that generates a formatted A4 landscape document containing all inspection records, outcomes, non-conformances, and actions. This is suitable for presenting to your certifier or an independent auditor." },
      { q: "What is parallel production and do I need to record it?", a: "Parallel production applies when a holding runs both certified organic and non-organic (conventional) land at the same time. This is permitted in some circumstances but must be disclosed to your certifier. The field status form has a parallel production checkbox — tick this for any field where this applies." },
      { q: "Can I log organic inspections and input register entries on my mobile?", a: "Yes. The mobile app includes a dedicated Organic Compliance hub screen showing your current certification status and next inspection countdown. From there you can log a new certifier inspection (capturing certifier name, inspection type, outcome, any non-conformances, and follow-up actions) or add an entry to the organic input register (product, supplier, field, quantity, unit, and approval reference). Both forms save offline if you have no signal and sync to the dashboard automatically when connectivity is restored. The same screens are also accessible from the Record tab in the app — tap Organic Inspection Record or Organic Input Register." },
      { q: "Can I attach the inspector's report to an organic inspection record?", a: "Yes. On the dashboard, each row in the Organic Inspections table has an Attach Document button. Click it to upload a PDF or image of the certifier's inspection report or outcome letter — for example a signed inspection summary from the Soil Association or OF&G. The document is stored permanently with the inspection record and is accessible instantly if an auditor asks to see the original paperwork alongside your structured records." },
    ],
  },
  {
    title: "Organic Arable",
    icon: Leaf,
    color: "bg-amber-50 text-amber-700 border-amber-100",
    items: [
      { q: "What is the Seed Stock Ledger and how does it differ from Seed Sourcing records?", a: "The Seed Sourcing register records each seed purchase as a declaration — crop, variety, lot number, supplier, certified organic flag, and derogation status — primarily for certifier audit evidence. The Seed Stock Ledger is a live inventory layer on top of that: it tracks the current balance of each unique seed lot by recording movements against it. A goods-in movement is created when seed arrives (with PO and GRN references); consumption movements are logged each time seed is drilled into a field (with field name and drilling date); adjustments handle stock corrections; and waste movements record losses. The running balance updates automatically after every movement. During harvest season you can see at a glance which lots have been fully used, which are partially remaining, and whether any stock is unaccounted for — giving certifiers a complete seed trail from receipt through to field use." },
      { q: "What field management tools are included with Organic Arable?", a: "The Organic Arable subscription bundles full access to Fields & Crops (field register with NVZ zone designation and organic conversion status badges), Field Operations (cultivations, drilling, rolling, lime spreading, drainage and all other fieldwork records), Field Inspections (crop walking logs, growth stage assessments, pest and disease pressure flags with action-required notes), Harvest Records (shared harvest register with yield, moisture, grade, and storage destination), Storage Locations (grain store and building register), and Crop Stock (stock position and movement tracking). You do not need a separate Field & Crop Management subscription to access any of these — they are included within the Organic Arable module at no additional charge." },
      { q: "Can I record organic arable seed stock movements on my mobile?", a: "Yes. The mobile app includes a dedicated Seed Stock Movement screen accessible from the Organic Arable section in the More tab. Select the movement type (Goods In, Seed Used / Drilled, Stock Adjustment, or Waste / Loss), enter the crop, variety, and batch or lot number, record the quantity in kg, and — for consumption movements — the field name and drilling date. The record saves offline if you have no signal and syncs to the dashboard automatically when connectivity is restored. The running balance is recalculated server-side after each sync." },
      { q: "How does the parallel production flag work for organic arable?", a: "If your holding runs both certified organic and conventional arable land at the same time, tick the Parallel Production flag on the Certification tab. An amber compliance panel immediately appears citing UK Organic Regulations 2020 and the requirement for prior written certifier approval and an annual notification. This flag is visible to your certifier during inspection and ensures it cannot be overlooked in your records." },
      { q: "Can I print organic arable records for a certifier inspection?", a: "Yes — every tab in the Organic Arable module has a Print Register button generating a formatted A4 landscape compliance report, and an Export CSV button. Reports carry your farm name and current date. The Seed Sourcing, Seed Stock Ledger, Input Log, and Harvest Declarations reports are each designed to answer the specific questions a Soil Association, OF&G, or Organic Farmers & Growers inspector will ask during a certification audit. Attachments (seed certificates, derogation approval letters, delivery notes) stored against individual records are accessible directly from the view dialog during inspection." },
      { q: "What is the Annex II SubstancePicker in the Input Log?", a: "The Input Log uses a searchable picker containing all 33 substances listed in Annex II of the UK Organic Regulations 2020 — covering permitted plant protection products, soil conditioners and fertilisers, cleaning agents, and pest control materials. Each substance carries a Permitted, Restricted, or Derogation Required status. Selecting a Restricted or Derogation Required substance makes the certifier approval reference field mandatory and displays an amber advisory panel requiring you to confirm certifier notification before saving. A free-text override is available for substances not on the list, ensuring no application goes unrecorded." },
    ],
  },
  {
    title: "Organic Livestock",
    icon: Sprout,
    color: "bg-emerald-50 text-emerald-700 border-emerald-100",
    items: [
      { q: "How does herd register linkage work in Organic Livestock?", a: "In the Conversion tab, select an existing herd or flock from your core Livestock Register. When you save the record, BDE Farm Trac automatically sets the isOrganicHerd flag on that herd — propagating organic status to Medicine Records (doubled withdrawal periods), Feed Management (organic approved flag), and Livestock Movements (organic movement flag). You do not need to update each module separately." },
      { q: "Can I attach the organic certificate to a conversion record?", a: "Yes. Each conversion record has an Attach Document button in the actions column. Click it to upload the PDF or image of the issued organic certificate or certifier acknowledgement letter. The document is stored permanently with the conversion record and is immediately accessible during a certifier audit or inspection. Accepted formats are PDF, JPG, PNG, and WEBP." },
      { q: "What is the parallel production annual notification requirement and how do I record it?", a: "Under the UK Organic Regulations 2020, if you keep organic and non-organic herds of the same species on the same holding (parallel production), you must notify your certification body annually that the parallel production arrangement is still in place. When you tick Parallel Production on a conversion record, an amber compliance panel appears in the Add / Edit dialog summarising this requirement. To record each year's notification, click the bell icon that appears in the actions column for any parallel production record. The Notification Manager dialog opens — add a record for the certification year with the date sent, the certifier's acknowledgement reference, and any notes. You can also attach the certifier's written acknowledgement for that year directly to the notification record." },
      { q: "Can BDE Farm Trac generate the annual parallel production notification letter?", a: "Yes. In the Notification Manager for any parallel production herd, each year's notification row has a Generate Letter button. Clicking it produces a pre-filled formal Annual Notification of Parallel Production Arrangements letter containing your operator name, holding address, CPH number, herd name and species, number of animals, conversion start date, a segregation measures checklist, a compliance declaration, and a signature block. The letter opens in a print dialog — print it directly or save as a PDF. You can then sign it and post or email it to your certification body. The certifier's response can be uploaded as a document against that year's notification record." },
      { q: "How does the Week Ahead Planner alert me about annual parallel production notifications?", a: "The Week Ahead Planner tracks the date of the most recent annual notification for each parallel production herd. Less than 10 months since the last notification — no alert. Between 10 and 12 months — an amber 'due soon' alert appears. More than 12 months, or if no notification has ever been recorded — a red 'overdue' alert appears. These alerts appear alongside the Expected Certification Date cards for in-conversion herds. No configuration is needed — the planner reads directly from the dates you have saved in the Notification Manager." },
      { q: "How are organic treatment records populated without double-entry?", a: "Any medicine record in your Livestock Medicine Register that is flagged as an Organic Treatment automatically appears in read-only green rows at the top of the Treatment Compliance tab. You do not re-enter these records. Standalone organic treatments (recorded directly in the Organic Livestock module) appear below. Both sources are included in the print-ready treatment register." },
      { q: "How is the doubled withdrawal period calculated?", a: "For treatments flagged as organic, BDE Farm Trac doubles the standard withdrawal period specified on the medicine record and calculates the Organic Withdrawal End Date from the last treatment date. This doubled date is displayed on every treatment row. A Raise Task button lets you assign a withdrawal-end verification task to a staff member with the date pre-filled." },
      { q: "How does the species-filtered herd selector work in the Feed Records and Outdoor Access tabs?", a: "When you select a species in the Feed Records tab (e.g. Dairy Cattle or Sheep / Lambs), the Herd / Flock selector automatically filters to show only herds of the matching species drawn from your Livestock Register. So if you select Dairy Cattle, only your dairy herds appear — not beef herds or sheep flocks. Organic-certified herds are shown with a 🌿 indicator. If no herds of the matching species are registered yet, a free-text herd name field appears as a fallback. The same filtered lookup is available in the Outdoor Access Log tab." },
      { q: "Do date fields default to today's date in organic livestock records?", a: "Yes. All date fields across the Organic Livestock module default to today's date when you open a new record — this applies to the Feed date in the Feed Records tab, the Access Date in the Outdoor Access Log, and the Treatment Date in the Treatments tab. For same-day field recording, no date entry is required. You can still overtype the date for retrospective records." },
      { q: "Can I record outdoor access periods and stocking density?", a: "Yes. The Outdoor Access Log tab records each access event with species, herd / flock name (filtered from the Livestock Register by species), access date, whether access was provided, duration in hours, number of animals, pasture area in hectares, compliance status (Compliant / Derogation / Non-Compliant), and a restriction reason if access was withheld. Stocking density and paddock area are also recordable. This gives certifiers the evidence they need to verify compliance with outdoor access requirements under EC 889/2008 or UK retained equivalents." },
      { q: "Can I print treatment and feed records for my certifier?", a: "Yes. Each of the four tabs (Conversion Register, Feed Log, Outdoor Access Log, Treatments Register) has a Print Report button that generates a formatted A4 printout with your farm name, current date, and the complete record set for that tab. These are designed to be handed to a certifier or attached to an inspection file without further formatting." },
      { q: "What is the Feed Derogations tab and when do I need it?", a: "Under UK Organic Regulations 2020, Article 22, you must obtain written approval from your certifier before feeding any non-organic ingredient to organic livestock. The Feed Derogations tab — between Feed Records and Outdoor Access in the Organic Livestock module — is where you manage one case per non-organic ingredient, tracking the full lifecycle from application through to approval, expiry, or rejection. Each case records the ingredient name, feed product, species covered, certifier, applied date, decision date, expiry date, regulatory category, availability search evidence, justification for use, and any conditions attached to the approval. Status chips at the top show your live position across Pending, Approved, Rejected, Expired, and Withdrawn cases at a glance." },
      { q: "How does the certifier correspondence log work in a derogation case?", a: "Expanding any derogation case card reveals a Correspondence sub-section. Each entry records the date, direction (To Certifier, From Certifier, or Internal), subject, body, and any notes. This gives you a complete, date-ordered paper trail of every communication with the certifier about that ingredient — application letters, queries, their decision letter, and any subsequent variation notices — all in one place. Entries can be added, edited, or deleted at any time. The correspondence log and the Documents section (for uploading the actual approval letter, your availability search evidence, and supporting paperwork) together form a complete dossier for each derogation case that is accessible instantly during a certification body inspection." },
      { q: "How does the derogation case link to a feed delivery record?", a: "When you record a feed delivery in the Feed Records tab and untick Organic Approved, a Link to Approved Derogation Case dropdown appears if you have any active approved derogation cases. Selecting a case auto-fills the Certifier Approval Reference and Regulatory Category fields on the feed record from the case file — so every non-approved delivery is tied directly to the written certifier approval that authorises it. If no approved case exists yet, a prompt directs you to the Feed Derogations tab to create one before logging the delivery." },
      { q: "Can I access standard livestock records from within the Organic Livestock section?", a: "Yes. The Organic Livestock page includes all 15 standard Livestock module tabs alongside the organic compliance tabs, so you do not need to navigate between modules. The standard tabs available within Organic Livestock are: Herds & Flocks (herd and flock register), Animals (individual animal register), Vet Health Plans, Mortality Records, Contractors, Feed (feed delivery records from Feed Management), Water (water supply and quality records), Sires (sire register), Straws (AI straw stock register), AI & Repro (AI and reproduction records), Vet Rx (veterinary prescription records), Lambing Records (with perinatal ABP disposal documentation), TB Tests (APHA-required TB test register), Welfare Outcome Assessments, and Sheep Dipping Records. Any improvements made to the standard Livestock module automatically appear within the Organic Livestock section as well — there is no duplication between the two." },
    ],
  },
  {
    title: "Organic Dairy",
    icon: Sprout,
    color: "bg-teal-50 text-teal-700 border-teal-100",
    items: [
      { q: "What is the milk certification date and how does it differ from the conversion date?", a: "Organic Dairy tracks two distinct dates for each herd: the Expected Milk Certification Date (when organic milk is anticipated to be accepted by your milk buyer, based on conversion progress) and the Actual Milk Certification Date (confirmed in writing by your certifier or buyer). These are separate from the general Fully Organic Date used in the Livestock conversion register. Both surface as separate event cards in the Week Ahead Planner." },
      { q: "How do milk collection records work?", a: "The Milk Collections tab logs every tanker uplift using a three-tab form: Collection Details (date, volume, collector, vehicle, processor ref, organic status, collection slip ref, witnessed by, deductions, net value), Quality & ABR (milk temperature at collection, fat %, protein %, lactose %, SCC, TBC, ABR result, ABR tester, kit lot and batch), and Buyer Lab Results (status, date, buyer lab reference, buyer SCC, TBC, fat %, protein %, lactose %). Records are filterable by date range and exportable to CSV for certifier audit evidence or reconciliation with your milk buyer's statements." },
      { q: "What is the ABR test result badge in the Milk Collections table?", a: "Every row in the Milk Collections table shows a colour-coded ABR (antibiotic residue test) badge. Negative results show a green badge; Positive results show a red badge with a warning; Borderline results show an amber badge; Invalid results show a grey badge. If no ABR test was recorded for a collection the badge is absent. This gives an instant compliance overview across all uplifts without opening individual records." },
      { q: "How do buyer lab results work?", a: "The Buyer Lab Results tab on each milk collection record holds the processor or buyer's independent quality analysis. Record the result status (Pending while awaiting results, Received when they arrive, or Failed if the buyer rejects the collection), the result date, the buyer's lab reference number, and the buyer-returned SCC, TBC, fat %, protein %, and lactose %. These figures sit alongside the on-farm readings recorded at collection, so any discrepancy between what was measured at the tank and what the processor reports is visible on the same record." },
      { q: "What is a retest and how does the retest linkage work?", a: "If an initial ABR result triggers a confirmatory retest before the collection is accepted, record the retest as a new collection entry with the 'This is a retest' flag turned on. An optional 'Retest of' picker then lets you select the original collection record that prompted the retest, creating a direct evidential link between the two records. The original record and the retest are displayed together in the table with the retest shown as a linked sub-record, giving inspectors a clear audit trail." },
      { q: "How does the dual withdrawal period work for dairy cattle?", a: "Dairy organic treatments carry two separate doubled withdrawal periods: one for organic milk and one for organic meat. Both end dates are displayed on every treatment row alongside the standard period. Two separate Raise Task buttons — one teal (milk) and one amber (meat) — let you assign an end-of-withdrawal check to a named staff member with the correct date pre-filled and an SMS notification sent on save." },
      { q: "How do organic feed records appear without double-entry?", a: "Feed deliveries recorded in Feed Management that are flagged as Organic Approved (with supplier approval number, organic %, and any derogation reference) appear automatically in the Feed & Nutrition tab of the Organic Dairy module. One entry, visible in both modules, with no re-keying required." },
      { q: "Do date fields default to today's date in Organic Dairy records?", a: "Yes. All primary date fields in the Organic Dairy module default to today's date when a new record is opened — Collection Date in the Milk Collections tab, Feed Date in the Feed & Nutrition tab, and Treatment Date in the Treatments tab. This makes same-day recording fast and reduces data entry errors from leaving a date field blank. You can overtype any of these to record retrospective entries." },
      { q: "Can I print dairy organic compliance records?", a: "Yes. Each of the four tabs (Herd Conversion, Milk Collections, Feed & Nutrition, Treatments) has a Print Report button generating a formatted A4 printout ready for certifier or auditor review." },
      { q: "Can I attach documents to Organic Dairy records?", a: "Yes. The full view dialog for Herd Conversion records, Milk Collection records, and Feed & Nutrition records each includes a RecordAttachments panel, allowing PDFs, photos, and Word documents to be linked permanently to any individual compliance record. This is available across the Organic Dairy module for cattle, sheep dairy, and goat dairy collections." },
      { q: "How does the feed derogation case linker work in the Feed & Nutrition tab?", a: "When a feed or nutrition record is marked as not organically approved (the 'Is Organic Approved' toggle is off), a Link to Approved Derogation Case picker appears below the certifier reference field. This picker lists all currently approved derogation cases from your Organic Livestock Feed Derogations register. Selecting a case automatically fills the Certifier Approval Reference and Derogation Reference fields on the dairy feed record from the case file — so the evidence link between the delivery log and the formal certifier approval is recorded without re-typing. If no approved derogation case exists yet, the picker prompts you to visit the Organic Livestock → Feed Derogations tab to create one before logging the delivery." },
    ],
  },
  {
    title: "Organic Fresh Produce",
    icon: Sprout,
    color: "bg-lime-50 text-lime-700 border-lime-100",
    items: [
      { q: "How does the Block Conversion Status Register work?", a: "The Block Status tab tracks the organic conversion status of each growing block — in-conversion, fully organic, or non-organic. For in-conversion blocks, a visual progress bar shows how far through the statutory conversion period the block is, with a days-remaining countdown to the expected fully-organic date. Each record stores the certifying body, conversion start date, pre-conversion land use, and synthetic history notes. You can print a formatted Block Status Register for certifier inspection from the Print Report button on the tab." },
      { q: "Can I link a growing block to a farm field?", a: "Yes. When adding or editing a growing block in the Fresh Produce module, an optional Parent Field picker lets you link the block to any registered farm field. The block then inherits the field's NVZ designation and organic status, which are displayed as badges on the block's detail view. This is designed for mixed farms where fresh produce blocks sit within broader field boundaries already registered in Field & Crop Management." },
      { q: "How do I record organic inputs applied to a block?", a: "The Input Log tab lets you log each approved input with the product name, date applied, quantity, unit, and purpose. You can link the input to a supplier from your Trade Contacts list and optionally attach a Purchase Order reference and GRN / Delivery Note reference for full audit traceability. The Applied By field uses a staff lookup from your farm team register. A Print Report button generates a formatted A4 input log for certifier presentation." },
      { q: "What are buyer declarations and how do I record them?", a: "Buyer declarations are written assurances issued to buyers confirming the organic status of the produce being sold. The Buyer Declarations tab records each declaration with buyer name, issue date, product, quantity, certifying body reference, and declaration status. Records use the view-before-edit pattern — clicking a row opens a read-only view dialog, and an Edit button within that dialog opens the edit form — ensuring records are reviewed carefully before any changes are made." },
      { q: "What is the Input Derogations tab in Organic Fresh Produce?", a: "Under the UK Organic Regulations 2020 (Schedule 1 / Annex II), certain inputs require prior written approval from your certification body before you can use them on organically-managed land — principally conventional seed where no certified organic equivalent is available, and restricted crop protection substances. The Input Derogations tab in the Organic Fresh Produce module is a dedicated register for these approvals. Each case records the input substance name and type, crop year, certifier, certifier reference, availability search date and OFAS / UKOAS reference number, application and decision dates, expiry date with colour-coded warnings (amber at 60 days, red at 14 days), justification for why no organic alternative was available, approval conditions, and the full regulatory basis. Status chips at the top of the tab — Pending, Approved, Rejected, Expired, Withdrawn — give you an instant compliance position across all active cases." },
      { q: "How does the FP input derogation correspondence log work?", a: "Expanding any derogation case card in the Input Derogations tab reveals a Correspondence Log sub-section. Each entry records the date, direction (sent to certifier or received from certifier), correspondence type (Application to Certifier, Availability Search Evidence, Approval Letter, Rejection Notice, Conditions Letter, and others), a summary of the content, and an optional certifier reference. This gives you a complete date-ordered paper trail of every communication with the certifier about that input — from your initial application through to their decision and any subsequent conditions letters — in a single dossier alongside the case record and uploaded documents." },
      { q: "Can I upload the certifier's approval letter to an FP input derogation case?", a: "Yes. Each case card in the Input Derogations tab has a Documents section. Click Upload to attach files — select the document type first (Availability Search Evidence, Application Letter, Approval / Decision Letter, Conditions Letter, Rejection Notice, Photographs, or Supporting Evidence) and then choose the file from your computer. Uploaded documents appear in the case's document list with a View link for instant on-screen access during a certifier inspection. Documents are stored in secure cloud storage and permanently linked to the case record." },
      { q: "Can I view FP input derogation cases on the mobile app?", a: "Yes. The Organic Overview screen in the mobile app has an FP Input Derogations quick action button that opens the full derogation case register. You can expand individual cases to view certifier details, application and expiry dates with urgency badges, availability search evidence reference, justification, and any approval conditions. When logging an FP input and you select 'Derogation Required' as the approval status, a View FP Input Derogation Cases link appears directly in the form so you can cross-reference the active approval before recording the reference. Full case management — adding cases, correspondence, and document uploads — is handled in the dashboard." },
      { q: "Can I log organic fresh produce inputs from the mobile app?", a: "Yes. The mobile app Organic Overview screen has a Quick Actions grid with buttons for Fresh Produce Input (log an input applied to a block with product, date applied defaulting to today, quantity, unit, purpose, supplier, and applied-by operator name), FP Input Derogations (view the full derogation case register with status chips and expandable case details), Outdoor Access Recording (date defaulting to today, hours, number of animals, pasture area in hectares, compliance status — Compliant / Derogation / Non-Compliant — and restriction reason, with herd / flock name filtered from the Livestock Register by species), and Organic Treatment (medicine product, product category, active ingredient, batch number, dose, route, standard withdrawal days with auto-calculated doubled organic withdrawal period, vet name, prescription reference, and certifier notification). All recording screens save data locally and sync to the dashboard when connectivity is restored." },
      { q: "Can I access standard fresh produce records from within the Organic Fresh Produce section?", a: "Yes. The Organic Fresh Produce page includes all six standard Fresh Produce module tabs alongside the organic compliance tabs, so you do not need to navigate between modules. The standard tabs available within Organic Fresh Produce are: Crops (growing block crop records), Water Tests (water quality testing log), Harvest (harvest records with yield and grade data), Intake (pre-cooling and intake records), Packhouse (packhouse and despatch records), and Allergens (allergen management register). Organic status badges from the Organic Fresh Produce module surface on all related block records within these tabs. Any improvements made to the standard Fresh Produce module automatically appear within the Organic Fresh Produce section as well." },
    ],
  },
  {
    title: "Biosecurity",
    icon: ShieldCheck,
    color: "bg-red-50 text-red-600 border-red-100",
    items: [
      { q: "Can I capture a digital signature for visitor sign-in?", a: "Yes. The mobile visitor log includes a full digital signature pad. Visitors can sign directly on screen using their finger or a stylus. The signature is stored with the visit record and syncs to the dashboard. The visitor declaration (confirming no contact with livestock in the past 72 hours and agreement to farm biosecurity rules) is displayed before signature capture. On mobile, you can also attach a photo directly to a new visitor record — for example a photo of a paper declaration, contractor ID, or vehicle permit — using the Attach Photo button that appears above the Log Visitor button. On the dashboard, existing visitor records have a full Attachments panel where you can upload PDFs, images, or Word documents such as scanned declarations, contractor certificates, or delivery paperwork." },
      { q: "How do I record pest control treatments?", a: "Navigate to Biosecurity > Pest Control. You can log each treatment event with the target pest, bait type, active ingredient, location, date, and the contracted pest controller's details. Records are filterable by crop year. From the dashboard, each pest control record also supports document and photo attachments via the Attachments panel on the record view — allowing you to store the pest controller's treatment report, risk assessment, site map, or invoice permanently alongside the structured record for Red Tractor audit purposes." },
      { q: "Can I print a COSHH register?", a: "Yes. The COSHH Assessments tab includes a Print Register button that generates a formatted A4 document with all your substance assessments, suitable for presenting to a Red Tractor inspector or health and safety auditor. Each COSHH record also has an Attachments panel on the dashboard where you can attach photos and documents — such as a scanned Safety Data Sheet (SDS), product label, or supplier data sheet — directly to the assessment record. On mobile, a dedicated Attach Safety Data Sheet Photo button lets you photograph the SDS on the spot and store it with the assessment when creating a new record." },
      { q: "What is the Cleaning & Disinfection log used for?", a: "This log records all cleaning and disinfection events across your farm buildings and areas — including the product used, dilution rate, contact time, who carried out the work, and the area cleaned. It satisfies the Red Tractor requirement for documented biosecurity procedures. From the dashboard, each Cleaning & Disinfection record also has an Attachments panel where you can upload photos of the completed disinfection process, product labels, delivery notes, or a completed checklist as additional photographic and documentary audit evidence." },
      { q: "What is the Feed Contingency Plan and why do I need one?", a: "Red Tractor requires livestock farms to have a documented plan for maintaining feed supply during a disruption — for example, a supplier withdrawal, transport failure, or a disease restriction that prevents deliveries. The Feed Contingency Plan section lets you record your minimum stock targets (days' cover and total kg alert threshold), your primary feed supplier, alternative suppliers with lead times, and written procedures covering trigger conditions, rationing, communication, and recovery. The plan carries a review date badge so you know when it is due for update. A Red Tractor inspector may ask to see this document." },
      { q: "How do I log a notifiable disease suspicion and report to APHA?", a: "Navigate to Compliance & Plans and open the Disease & Incident Log tab. Click Log Incident and set the Incident Type to Notifiable Disease. A red alert will appear reminding you to contact APHA immediately on 03000 200 301 — do not wait for laboratory confirmation. A dropdown lets you specify the disease type (FMD, Bluetongue, Avian Influenza, African Swine Fever, Brucellosis, bTB, Anthrax, and others). Record the vet response, any isolation and movement restriction applied, and the APHA reference number once you have reported. You can also select affected herds from the Herd Register using the multi-select picker, and pick specific individual animals by ear tag from the Individual Animal Register. Any animals recorded as mortalities in the incident are automatically marked as deceased in the Individual Animal Register when you save. The incident remains open until an outcome and lesson learned are recorded and you set the status to Resolved." },
      { q: "How do I raise a feed recall or withdrawal incident?", a: "Go to Compliance & Plans and open the Feed Recall & Withdrawal Incidents tab. Click Raise Incident and select the concern type — contamination, mislabelling, supplier-issued recall, disease link, or regulatory advice from APHA or Trading Standards. Enter the product name (autocompletes from your delivery records), supplier (selected from your Supplier Register), and batch or lot number. Record whether the feed has been physically withdrawn, which herds or groups were affected, and the estimated number of animals. Use the Notifications section to log when you notified the supplier, a regulatory authority, and your vet — with reference numbers and dates for each. Once the situation is resolved, record the outcome and close the incident." },
      { q: "How do I manage contractor Health & Safety files and reviews?", a: "Navigate to Safety, Risk & Audits > Contractor H&S File. Each contractor in your register has a dedicated H&S file capturing company details, the type of work they carry out, Public Liability Insurance details (insurer, policy number, cover level, and expiry date with a 30-day advance alert), Employer's Liability Insurance, RAMS received and review date, and farm induction status. The H&S Reviews tab within each contractor file lets you log dated review events — choose from Annual Review, RAMS Update, Insurance Renewal, Induction Completed, or Risk Assessment Review — recording the reviewer name, outcome notes, and next review due date. Upcoming reviews surface in the Farm Planner with amber and red alerts before they fall due. Clicking Raise Task on any review record lets you assign the follow-up action to a named staff member, who is notified by SMS. Once a contractor has an active H&S file, a green H&S File badge appears on their record in your Supplier register so you can confirm at a glance that contractor compliance is in order before engaging them for work." },
    ],
  },
  {
    title: "Sprays & Inputs",
    icon: FlaskConical,
    color: "bg-amber-50 text-amber-700 border-amber-100",
    items: [
      { q: "Does the spray record module meet Red Tractor requirements?", a: "Yes. The spray record form captures all fields required by Red Tractor Combinable Crops and Horticulture standards: crop, field, product name, MAPP number, application date, rate per hectare, total area, operator, and equipment. Records can be printed as a formatted spray register directly from the dashboard." },
      { q: "How do I log pesticides bought for the season?", a: "The Sprays & Inputs module includes a Pesticide Purchases log. Record the product, supplier, quantity, batch number, invoice reference, and date. These records link to your spray records for traceability and satisfy the purchase-to-application audit trail required by assurance schemes." },
      { q: "Can I record buffer zones and weather conditions on spray records?", a: "Yes. Each spray record includes fields for wind speed, wind direction, temperature, and buffer zone distances. These fields satisfy the requirements for operator protection and environmental protection under the Code of Practice for Using Plant Protection Products." },
      { q: "Can I record the cost of a spray product on an application record?", a: "Yes. Each spray application record includes a Product Cost (£/unit) field — enter the cost per litre, kg, or other applicable unit from the product invoice. The Season Production Report uses this figure alongside the application rate and area to calculate the total spray input cost for the season and incorporate it into the gross margin calculation. You can enter this at the time of spraying or fill it in later once the invoice is received. On the mobile app the same field appears in the Spray Record screen and syncs to the dashboard automatically." },
      { q: "Do all spray products require beekeeper and neighbour notification, or only some?", a: "Only products whose label carries a 'harmful to bees' or bee precaution statement require notification — this is primarily insecticides (pyrethroids, organophosphates, certain carbamates) and a small number of fungicides applied during flowering. Herbicides and most fungicides do not require beekeeper notification. In BDE Farm Trac, open the Product Register and tick the 🐝 Harmful to Bees checkbox on any product whose label carries a bee precaution statement. Unmarked products are not flagged for notification." },
      { q: "How does the 48-hour notification check work?", a: "When you log a notification, enter both the notification date and the planned spray date. The system immediately calculates the gap and shows a green badge (meeting the 48-hour requirement) or a red badge (under 48 hours). The same check runs across all existing records — a summary card at the top of the Notifications tab shows how many notifications in the current log have sub-48-hour lead times. Red Tractor assessors examine the gap between notification date and spray date, so the badge gives you an instant compliance signal." },
      { q: "What is the Contact Book in Spray Notifications?", a: "The Contact Book is a saved directory of your regular beekeepers and neighbouring landowners. Click the Contact Book button on the Notifications tab to add contacts with their type, name, phone/email, and postal address. When logging a new notification, open the quick-pick dropdown at the top of the form to select a saved contact — all fields (name, contact, address, recipient type) pre-fill instantly. This makes repeat notifications — for example, the same beekeeper contacted each season — take seconds rather than minutes." },
      { q: "How do I generate a formal notification letter for a beekeeper or neighbour?", a: "Click the printer icon on any notification row in the Notifications tab. BDE Farm Trac generates a formal, print-ready letter pre-filled with your farm name, address, and CPH number from Farm Settings, the recipient's name and postal address, and a table of planned spray details (date, products, fields affected). Beekeeper letters include a request to take hive precautions; neighbour letters reference the Voluntary Initiative Code of Practice. The letter opens in your browser's print dialog — print directly or save as PDF." },
      { q: "Does the Week Ahead Planner remind me to notify beekeepers before I spray?", a: "Yes — this is automatic once you have marked a product as harmful to bees. When a spray application is logged with a bee-precaution product and no notification has been recorded for it yet, the Week Ahead Planner shows an amber card titled 'Beekeeper Notification Required — [Product]' due-dated 48 hours before the spray date. If the deadline passes without a notification being logged the card turns red in the overdue section. Once you log the notification in Sprays & Inputs → Notifications, the planner card disappears on the next refresh." },
      { q: "What is BeeConnected and should I use it alongside the Notification Log?", a: "BeeConnected (beeconnected.org.uk) is a free service run by BBKA and Bayer that automatically alerts registered beekeepers within a set radius of your fields when you log a planned spray — without you needing to identify or contact them individually. We recommend registering on BeeConnected for automatic coverage of registered beekeepers, and using the BDE Farm Trac Notification Log to document any beekeepers not registered with BeeConnected and all neighbouring landowner notifications. The BeeConnected information panel on the Notifications tab includes a direct link to the service." },
      { q: "How does the Spray Store Stocktake work?", a: "Open the Sprays & Inputs page on the dashboard and navigate to the Stocktakes tab. Click Record Stocktake to open the dialog. Select the spray product from the registered product list — the system quantity auto-fills from that product's current stock record, so you can see at a glance what BDE Farm Trac believes is in the store before you start counting. Enter the physical quantity measured in litres. A variance badge appears immediately: green for zero variance, amber if your physical count exceeds the system figure (surplus), and red if it falls short (shortfall). Enter who conducted the stocktake, confirm the date, add any notes about the count conditions or discrepancy cause, and click Save. The record is written to the stocktake history and is visible in the table immediately. On the mobile app, tap 'Spray Store Stocktake' in the Record tab — the product picker, system quantity auto-fill, and variance badge all work offline, syncing to the dashboard when connectivity is restored." },
    ],
  },
  {
    title: "Livestock & Medicine",
    icon: PawPrint,
    color: "bg-rose-50 text-rose-600 border-rose-100",
    items: [
      { q: "What movement records does BDE Farm Trac capture?", a: "The Livestock module records all movements on and off the holding, including species, ear tag, date, origin and destination holding number, and transport details. Records cover cattle, sheep, goats, pigs, deer, and equines. The Movements register includes the AML reference field, BCMS status badge, and one-click submission buttons for cattle (BCMS via CTS Web Services and LIS LIP via OAuth) and sheep, goats and deer (LIS via the England CLA API). Each movement can also be linked to individual animals from your Animal Register — off-holding movements let you pick the animals being sold directly from a searchable register, and on-holding movements let you register the arriving animals' ear tags so they are created automatically in the register." },
      { q: "How does individual animal linking work on livestock movement records?", a: "When recording an off-holding movement (sale or dispatch), an Animal Register Picker appears alongside the movement form. Search your active animals by ear tag or tag number, filter by species, and tick the animals being moved — you can select as many as needed. On save, those animals are linked to the movement in a junction table and their individual status is automatically updated to Sold in the Individual Animal Register. When recording an on-holding movement (purchase or arrival), a Register Incoming Animals section lets you enter the arriving animals' ear tag numbers (one per line or comma-separated) plus a default breed and sex. On save, a new Animal Register entry is created for each tag, their status is set to Active, and they are linked to the movement. In the movement view, a Linked Animals panel shows every animal tied to that record — ear tag, breed, and sex — giving you a precise per-movement audit trail of individual animals." },
      { q: "How does BCMS one-click submission work for cattle?", a: "In Farm Settings, enter your CTS Web Services username and password under the BCMS / CTS One-Click Submission section and click Test Connection. Once connected, each cattle movement row in the Movements register shows a Submit to BCMS button. Clicking it sends the movement directly to the British Cattle Movement Service and stores the BCMS reference back against the record. A BCMS Submissions tab in the Movements register shows the full history of submissions, statuses, and any error messages. Sandbox mode is active until your DEFRA vendor credentials are configured — in sandbox mode the full API payload is logged and simulated without sending data to BCMS." },
      { q: "How does LIS one-click submission work for sheep, goats and deer?", a: "In Farm Settings, enter your Livestock Information Service username and password under the LIS / Livestock Information Service section and click Test Connection. Once connected, a blue Submit to LIS button appears on each sheep, goat and deer movement row. Clicking it opens a confirmation dialog showing the movement details before submitting directly to the England government CLA API (Livestock Information Service). A LIS Submissions tab in the Movements register shows the full history with LIS reference numbers, submission status, and the JSON payload sent. Sandbox mode is active until BDE's platform subscription key is registered — sandbox submissions are fully simulated with no data sent to LIS." },
      { q: "How does LIS LIP one-click submission work for cattle?", a: "LIP (Livestock Information Platform) is the LIS-operated cattle reporting system. In Farm Settings, scroll to the Livestock Information Platform (LIP) section and click Connect LIS Account. A new browser tab opens the government LIS sign-in page — sign in with your existing LIS credentials. Once authenticated, Farm Settings shows a Connected badge and the connection is stored securely against your farm holding. Each cattle movement row in the Movements register then shows a Submit to LIP button. Clicking it submits the movement directly to the LIP API and stores the reference number against the record. LIP submission also covers cattle births and deaths. A dedicated LIP Submissions tab shows the full submission history — reference numbers, status, and JSON payload. In a multi-farm account each holding connects its own LIS account independently." },
      { q: "What is the difference between BCMS and LIS LIP for cattle?", a: "Both BCMS (British Cattle Movement Service, via CTS Web Services) and LIS LIP (Livestock Information Platform, via LIS OAuth sign-in) are government cattle reporting routes supported by BDE Farm Trac. BCMS is the established England and Wales cattle tracing system managed by APHA; LIP is the newer LIS-operated cattle platform. Both are accessible from the same cattle movement row in the Movements register. For sheep, goats and deer, the England CLA API (Livestock Information Service) is the relevant reporting route — a separate integration also available in Farm Settings." },
      { q: "Can I link a livestock purchase invoice to a movement record?", a: "Yes — this is a compliance feature built directly into the Livestock Purchases tab in Finance. When adding or editing a purchase invoice, a Movement Record panel (labelled Compliance) appears below the Notes field. You can link the invoice to an existing incoming movement via a searchable dropdown (showing movement date, head count, species, from-location, and licence number), or use the Create & link button to auto-create a new on-holding movement pre-filled from the invoice data (arrival date, head count, species, supplier CPH as the from-location). Once linked, the invoice row shows a green Movement linked badge, and the panel displays the movement date, head count, movement licence, BCMS reference, and from-location together in one view. This creates a permanent database link from invoice number through to BCMS submission reference — the full purchase-to-notification audit trail required by Red Tractor." },
      { q: "How do I link a deadweight or mart sale to its off-farm movement record?", a: "Open the Livestock Trading page on the dashboard and add or edit a deadweight kill sheet (Deadweight tab) or mart sale (Mart / Auction tab). Near the bottom of the form, a 'Link to Off-Farm Movement Record' dropdown lists all your outgoing livestock movements — those recorded with movement type Off, Sale, or Dispatch. Select the matching movement to link the sale record directly to the BCMS notification for that consignment. Once saved, a green Movement badge appears on the kill sheet or mart sale row in the table. This cross-reference creates the full audit trail from sale document to BCMS movement record that Red Tractor and AHDB require. If no movements appear in the dropdown, first log the off-farm movement on the Livestock page (Movements tab) with movement type set to Off, Sale, or Dispatch." },
      { q: "Can I attach the kill sheet or lot sheet document to a deadweight or mart sale record?", a: "Yes. Every row in the Deadweight and Mart / Auction tables has a Doc column with a paperclip icon. Click the paperclip on any row to upload a PDF or image of the abattoir kill sheet, deadweight settlement printout, or auctioneer lot sheet. Once uploaded, the icon changes to a file icon — clicking it opens the document in a new tab. A small × next to the file icon lets you remove and replace the attachment. Documents are stored in cloud storage and permanently linked to the record so they are instantly accessible during a Red Tractor, AHDB, or bank audit without having to search through paper files." },
      { q: "How do I link a TB pre/post-movement test to its movement record?", a: "Open the Livestock page on the dashboard and select the TB Test Register tab. Add a new test or edit an existing one. When the Test Type is set to Pre-Movement or Post-Movement, a 'Link to Livestock Movement Record' dropdown appears listing your outgoing off-farm movements. Select the movement this test was conducted for — the dropdown shows the movement date, type, species, head count, destination, and AML licence number. For all other test types (Routine, Short Interval, Contiguous, Gamma IFN) the movement link field is also available as an optional field. Once saved, a green Movement badge appears on the test row. This satisfies the APHA requirement to evidence that a pre-movement test was conducted and linked to the specific movement it cleared, and provides the cross-reference for cross-compliance TB inspections." },
      { q: "How are medicine withdrawal periods tracked?", a: "Each medicine record includes the product name, batch number, dose, route of administration, withdrawal period in days, and the treated animal's identifier. BDE Farm Trac automatically calculates the withdrawal end date and surfaces a warning if any animal with an active withdrawal period is recorded as sold or slaughtered." },
      { q: "Can I record AI and reproductive events?", a: "Yes. The Reproduction module covers AI records (sire, breed, method, straw batch traceability), pregnancy confirmations, and expected calving/lambing dates. Expected birth dates feed automatically into the Farm Planner calendar." },
      { q: "Is the feed traceability log Red Tractor-compliant?", a: "Yes. Each feed delivery record captures supplier, UFAS/FEMAS number, delivery note and invoice reference, feed type, batch/lot number, quantity, and unit price. Medicated feeds are flagged with withdrawal period end dates. This satisfies the feed materials traceability requirements of Red Tractor Beef & Lamb, Dairy, and Pigs standards." },
      { q: "How do I navigate quickly from a Week Ahead alert to a specific feed bin?", a: "Feed stock alerts on the Week Ahead page — including low stock, out of stock, and awaiting delivery notifications — are linked directly to the specific feed bin that triggered them. Clicking the alert takes you straight to the Feed Management page, which automatically opens the Feed Bins tab, scrolls to the relevant bin card, and highlights it with a coloured ring for a few seconds so it is immediately obvious which bin needs attention." },
      { q: "How does the Raise Reorder button work on a feed bin?", a: "On any feed bin card showing a Low Stock or Out of Stock status, a Raise Reorder button appears at the bottom of the card (only when no order is already in progress). Clicking it opens a dialog showing the bin name, supplier, and current stock level. You can optionally enter an expected delivery date and any notes for the bin record. You can also assign the reorder task to a named staff member — select them from the dropdown, add a task due date and a note to them (for example, the supplier phone number or the quantity to order). If that staff member has a mobile number registered in BDE Farm Trac, an SMS is sent to them automatically with the task title, due date, and your note. Clicking Confirm Reorder Raised marks the bin as Awaiting Delivery — suppressing the low/out-of-stock alerts on Week Ahead — and creates a Task Board entry assigned to the chosen staff member with a direct link back to that bin for tracking." },
      { q: "How do I record vet visits and reconcile vet invoices?", a: "Navigate to Livestock > Vet Ledger. The Vet Visits tab lets you log every vet attendance — record the date, vet name and practice, reason for the call, affected herds or individual animals from the register, clinical findings, diagnoses, medicines administered (with batch numbers and withdrawal periods), prescription references, and any follow-up required. Follow-ups appear as a due count on the Vet Ledger summary cards and in the Farm Planner. The Invoices tab records each invoice from your vet practice with line items typed by category — call-out fee, consultation, medicines, lab tests, TB testing, scanning, or other procedures. Each invoice line can be linked back to the specific visit it relates to. Reconciliation status (Unreconciled / Partially Reconciled / Reconciled) is calculated automatically from how many lines have been matched to visits. Payment status is tracked separately from reconciliation — an invoice can be paid but still have unmatched lines." },
      { q: "How do I record vet visit medicines with withdrawal period tracking?", a: "When logging a vet visit in the Vet Ledger, use the Medicines Administered section to add one row per product. Record the medicine name, batch number, quantity, dose, route of administration, and withdrawal period in days. Mark each medicine as either Vet-Dispensed (the vet supplied the product at the visit) or Used from your own on-farm medicine stock. For medicines used from stock, you should also record them in the Medicine Records register under the Livestock module so that they appear in your medicine usage audit trail with withdrawal period warnings. Full withdrawal period tracking — including automatic calculation of the end date and slaughter or sale warnings — is managed in the Medicine Records register." },
      { q: "Can I use a Bluetooth RFID scanner to enter ear tag numbers in the mobile app?", a: "Yes. The BDE Farm Trac mobile app supports Bluetooth RFID wands that operate in standard keyboard-wedge (HID) mode — the reader pairs to your phone as a Bluetooth keyboard, so no specialist app or driver is needed. Compatible readers include the Tru-Test SRS2, Agrident ABR100, Zee Tag BRT1, and Gallagher HR2. To pair your reader, go to Settings → Equipment → RFID Reader in the mobile app for step-by-step pairing instructions. Once paired, every ear tag field across the app shows a small Bluetooth scan button next to it. Tap the button to enter scan mode (the field border turns green and a pulsing indicator appears), then hold the wand near the animal's ear tag — the 15-digit EID number is detected automatically and entered into the field with haptic confirmation. On livestock movement records, each scan appends a new tag to the list for quick batch entry of multiple animals. RFID scanning is supported on calving records (cow and calf tags), lambing records (ewe and all lamb tags), livestock movement records, medicine records, and mortality records." },
      { q: "What enhanced information can I record on a TB test?", a: "The TB Test Register captures test date, read date, Official Veterinarian name (auto-populated from your Vet Health Plans with the vet's phone and practice address pre-filled), test type (Routine, Pre-Movement, Post-Movement, or Short Interval Test), number of animals tested, result, APHA breakdown reference, and restriction status. Each herd's TB test record shows a complete history panel listing all previous tests in date order so you can track testing intervals at a glance. You can print an individual test certificate or the full herd TB test history — both are formatted for APHA submission or Red Tractor audit. Upcoming test read dates are surfaced automatically in the Farm Planner as reminder task cards assigned to the relevant staff member." },
      { q: "How do Welfare Outcome Assessments work?", a: "Navigate to Livestock > Welfare Outcome Assessments. Select the assessment type and species — the herd picker filters to show only herds of the matching species. Welfare outcome measures adapt automatically to the selected species: cattle, sheep, pig, and poultry assessments each present only the indicators relevant to that type. Next, choose the assessor type: Staff Member (selected from your staff register, name auto-populated) or External Assessor (selected from your Supplier register — a vet practice, consultant, or contracted assessor service). For external assessors, enter the expected assessment fee and BDE Farm Trac automatically generates a linked purchase order (PO-YYYY-NNNN) when the record is saved, so the cost flows straight into your procurement trail. For internal staff assessors, a Walkthrough Observations tally dialog lets you record animal counts per observation category directly during the walkthrough — tally values feed the calculated outcome scores automatically. Record the overall outcome (Good / Satisfactory / Action Required), any corrective actions taken, and the follow-up date. Each record uses a view-before-edit panel, and a Print Report button generates a formatted A4 report for your Red Tractor assessor. From the mobile app, tap Record > Welfare Outcome Assessment to log an assessment offline in the field." },
      { q: "What information can I capture on a fallen stock / mortality record?", a: "Mortality records include the full fallen stock contractor details — company name, address, phone, collection vehicle registration, collection reference number, and exact collection date and time. A veterinary declaration section records the declaring vet's name, RCVS or CVL number, and the date of declaration. You can also capture invoice information for the collection — invoice reference, invoice amount, and payment status. Together with the cause of death, disposal method, and BCMS mortality notification reference, this gives you the complete contractor and regulatory evidence trail required for Red Tractor mortality and fallen stock audit requirements." },
      { q: "How do I link a medicine treatment to a written vet prescription?", a: "When adding or editing a medicine record, a Vet Prescription field is available alongside the product details. Click the prescription picker to search your stored vet prescriptions by product name, vet name, or date — the searchable dropdown lists all active prescriptions in your Prescription Register. Selecting a prescription auto-populates the prescription reference number, dispensing vet name, and dispensing date on the medicine record. This removes manual re-entry and ensures that every treatment record traces back to the specific written authorisation under which the medicine was dispensed — a requirement of Red Tractor and VMD medicines regulations for all prescription-only veterinary medicines (POM-V and POM-VPS)." },
      { q: "How does the sheep dipping pesticide certificate auto-fill work?", a: "When logging a sheep dipping event, select the operator from your staff register. BDE Farm Trac looks up that person's PA6AW certificate from your Staff & Training certificate register — if a valid certificate is found, the certificate number and expiry date are auto-populated on the dipping record and a green 'Certificate verified' indicator appears. If the certificate is expired, an amber warning badge appears instead, prompting you to check whether the operator is still qualified to carry out the dipping. You can also manually enter the certificate number if the operator's records are held elsewhere. Stock usage for the dip product is recorded against your pesticide and chemical stock at the point of saving the record, keeping your on-farm stock balances current for COSHH and Red Tractor traceability." },
      { q: "How do I record perinatal disposal for stillborn or died-within-24h lambs?", a: "When any lamb on a lambing record is recorded as 'Stillborn' or 'Died within 24 hours', an amber Perinatal Disposal section automatically appears in the record form. Under the Animal By-Products (Enforcement) (England) Regulations 2011, these animals must be disposed of by an approved Animal By-Products (ABP) contractor and the disposal must be documented. The disposal panel captures: the approved Fallen Stock Contractor (selected from your registered contractors — including NFAS scheme contractors such as NFU Mutual Fallen Stock and Hunt Kennels), the collection date, the consignment note or NFAS certificate reference number, free-text disposal method (for cases without a registered contractor, such as an on-farm licensed incinerator), and disposal notes. Each lambing record card in the list shows a green 'Disposal recorded ✓' badge or a red 'Disposal not recorded' badge so non-compliant records are immediately visible. The view dialog shows either a green confirmation panel with the contractor and collection details, or a red warning prompting you to edit the record and add the disposal documentation. The audit report flags any record with perinatal deaths but missing disposal data with 'DISPOSAL NOT RECORDED' in red — exactly the kind of gap a Red Tractor Sheep Assurance assessor would identify. On mobile, the Perinatal Disposal section also appears automatically in the Lambing Record screen when a stillborn or died-within-24h outcome is selected; collection date, consignment ref, and disposal method can be captured in the field and synced to the dashboard." },
      { q: "How do the perinatal mortality analytics and season-by-season trend work?", a: "The Lambing tab on the Livestock page displays a Perinatal Mortality Analytics panel above the records list. For the currently selected lambing season, it shows five KPI tiles: Ewes Lambed, Total Lambs Born, Stillborn count and percentage, Died Within 24h count and percentage, and combined Perinatal Loss percentage. The percentage figures are colour-coded green (below 2%), amber (2–5%), or red (above 5%) — broadly aligned with the performance thresholds Red Tractor assessors expect to see actively monitored and explained. When two or more seasons of lambing data are present, a Season-by-Season Perinatal Mortality Trend comparison table appears beneath the KPI tiles. It shows each lambing season with its ewes lambed, total born, stillborn count and %, died-within-24h count and %, combined perinatal loss, and an inline bar chart visualising the trend. The same KPI summary and trend table are reproduced in the lambing audit report printout, making the analysis immediately available to a Red Tractor assessor without additional preparation." },
      { q: "How does Dry Cow Therapy (DCT) recording work in BDE Farm Trac?", a: "The Dry Cow Therapy tab is found under Dairy Management on the main dashboard. You begin by selecting the treatment protocol — Selective Dry Cow (antibiotic tube plus teat sealant), Blanket Dry Cow (antibiotic tube only), or Teat Sealant Only. Enter the cow's ear tag and BDE Farm Trac automatically pulls in her last recorded somatic cell count (SCC) and the number of mastitis cases in the preceding 12 months — key figures for justifying a selective protocol decision under RUMA guidelines. The antibiotic tube and teat sealant products are chosen from a searchable VMD intramammary medicine database; selecting a product auto-fills the standard milk and meat withdrawal periods in days so you never need to look them up manually. You can also enter the cow's expected calving date and the system will immediately calculate whether the antibiotic withdrawal will have cleared before calving, displaying a coloured compliance advisory. On save, BDE Farm Trac automatically creates a corresponding entry in the Medicine Records register and — for antibiotic protocols — a linked Vet Ledger visit record so every DCT event has an unbroken finance audit trail from prescription through to invoice." },
      { q: "What is POM-V enforcement in the DCT tab and why does it matter?", a: "POM-V stands for Prescription Only Medicine — Veterinarian. Under the Veterinary Medicines Regulations 2013, all intramammary antibiotics used in Dry Cow Therapy are POM-V products and may only be supplied or administered against a written veterinary prescription. When you select a Selective or Blanket Dry Cow protocol in BDE Farm Trac, the form requires you to confirm POM-V authorisation and to record the prescribing vet's name before the record can be saved. This is not a soft reminder — the save button stays disabled until the authorisation toggle is switched on. The prescribing vet name is taken from your registered Vet Health Plans rather than typed as free text, ensuring consistency across your medicines audit trail. This enforcement helps demonstrate to a Red Tractor Dairy or RUMA assessor that every antibiotic DCT treatment was carried out under valid veterinary authorisation, as required by the Responsible Use of Medicines in Agriculture Alliance (RUMA) dairy guidelines." },
      { q: "How does the DCT estimated prescription fee flow through to the Vet Ledger for invoice reconciliation?", a: "When logging a DCT record, there is an Estimated Prescription Fee (£) field. Enter the expected cost of the vet's prescription — this might be the fee your practice quoted at the time of authorisation. On save, BDE Farm Trac automatically creates a Vet Ledger visit record for the prescribing vet, with the visit reason set to 'DCT prescription authorisation' and the estimated amount written against it. In the Vet Ledger, these auto-created DCT visits display an amber 'DCT — invoice expected' badge so you can immediately see which vet prescription costs are not yet matched to a formal invoice. When the actual invoice arrives from your vet practice, click the Raise Invoice button on any unreconciled DCT visit — the invoice dialog pre-fills with the vet's name, the dry-off date, the estimated amount, and the linked visit ID. You then only need to adjust the final figure if it differs from the estimate and confirm. This creates a complete prescription-to-invoice audit trail without any manual cross-referencing between your DCT records and your vet invoices." },
    ],
  },
  {
    title: "Soil & Environment",
    icon: LeafyGreen,
    color: "bg-teal-50 text-teal-700 border-teal-100",
    items: [
      { q: "Does the Soil Management module cover NVZ rules?", a: "Yes. The NVZ Compliance section records your NVZ designations, closed-period restrictions, and slurry / organic manure spreading events. It calculates your annual nitrogen loading and compares it against the 170 kg N/ha limit, with a warning flag if you exceed the threshold." },
      { q: "Can I log soil samples and RB209 applications?", a: "Yes. The Soil Sampling log records each sample with GPS location, depth, analysis laboratory, and results for pH, P, K, Mg (indices) plus organic matter. A separate Nutrient Management Plan section lets you record your planned applications in line with FACTS/RB209 guidance." },
      { q: "Does BDE Farm Trac integrate with soil moisture sensors?", a: "The Soil Management module supports manual soil moisture deficit (SMD) logging. For continuous sensor integration, contact us — sensor connectivity is on our development roadmap." },
      { q: "Is there a dedicated page for managing SFI and ELM agreements?", a: "Yes. BDE Farm Trac includes a dedicated SFI / ELM page accessible directly from the sidebar under the Environmental module. It provides a full-page agreement register where you can add, view, edit, and delete SFI, Countryside Stewardship, and ELM agreements and their individual action or option codes. Evidence-due deadline alerts appear automatically in amber (within 60 days) and red (within 14 days) as review or submission dates approach. A print-ready compliance report is available from the page for RPA inspection visits." },
      { q: "How does the Slurry & Manure store register work?", a: "The Slurry & Manure tab in the Environmental page holds a full store register. Each store record captures the store name, type (earth-banked lagoon, above-ground tank, reception pit, etc.), material type (e.g. Cattle Slurry, Pig Slurry, Poultry Manure), capacity in m³, operator responsible, and build date. The stores table shows a live fill-level progress bar for each store — colour-coded green, amber, or red — calculated from the total volume of fill events logged against that store relative to its registered capacity. Clicking a store row opens a detail panel with a full capacity gauge dial alongside the store specification." },
      { q: "What is the Fill & Intake Events log?", a: "The Fill & Intake Events section is a dedicated sub-register within the Slurry & Manure tab that records every occasion material is received into a store. Each event captures the store, date, material type, volume added (m³), and source or origin (e.g. cattle housing, dirty water, import from off-farm). The events table shows the material type as a green pill badge for quick visual confirmation. These events feed the fill-level progress bars on the stores table and provide a permanent intake audit trail to sit alongside your spreading records — both are needed to demonstrate that your nitrogen budget calculations are based on the correct inputs." },
      { q: "What is species-specific storage enforcement and why does it matter?", a: "Species-specific storage is the requirement — set out in RB209 and the Nitrates Regulations — to account separately for slurry from different livestock species when calculating nitrogen loadings and NVZ compliance. BDE Farm Trac enforces this at the store level: when a store has a Material Type configured (for example 'Cattle Slurry'), the Manure Type field on the spreading form and the Material Type field on the fill event dialog are replaced with a 🔒 locked display the user cannot override. This prevents a cattle slurry store from accidentally being used to record pig slurry spreading or vice versa. The same rule is enforced server-side — if an API call attempts to log a fill event with a material that does not match the store's configured type, the server rejects it with a 422 error and a descriptive message explaining which material the store accepts. This hard lock ensures your nutrient management records are correctly split by species from point of entry, removing the risk of the audit trail being questioned by an NVZ inspector or cross-compliance officer." },
      { q: "Can I record slurry spreading and store fill events on the mobile app?", a: "Yes — both are available as dedicated screens in the BDE Farm Trac mobile app. The Slurry / Manure Spreading screen lets you select the source store from your registered stores, auto-locks the material type to the store's configured species, select the destination field using the field picker, and record volume, area, application rate, application method, soil condition (with run-off warnings for wet or saturated ground), contractor, and NVZ closed-period status. The Slurry Store Fill / Intake screen lets you select the receiving store, confirms the locked material type, captures volume added and source description, and includes a live capacity bar showing what percentage of the store's capacity the intake represents. Both screens save offline and sync automatically when connectivity is restored." },
      { q: "Is silage and haylage recording separate from slurry and manure management?", a: "Yes. The Silage & Haylage tab sits alongside Slurry & Manure in the Environmental module and uses its own store type — Silage Clamp — so a clamp's fill events, quality tests, and safety checks are kept distinct from slurry and manure store management, even though both share the same underlying store register. Additive/inoculant records, dry matter and quality tests, and clamp-specific safety checks are only available on stores typed as a silage clamp." },
      { q: "What happens if a silage quality test comes back with low dry matter?", a: "If a logged dry matter test result comes back below 25%, BDE Farm Trac automatically raises a high-priority task flagging the elevated effluent risk associated with wetter silage, and prompting you to check the clamp's drainage and effluent containment in line with the Silage, Slurry and Agricultural Fuel Oil (SSAFO) Regulations." },
      { q: "What extra checks apply to silage clamp safety inspections?", a: "Silage clamp inspections include the same checks used for slurry stores, plus additional SSAFO structural checks specific to clamps: effluent containment, cover sheet integrity, and wall soundness. A failed effluent-containment check raises an urgent task warning of a pollution risk and recommends checking drainage or collection arrangements and pausing filling until the issue is resolved." },
    ],
  },
  {
    title: "Staff & Training",
    icon: ClipboardCheck,
    color: "bg-indigo-50 text-indigo-600 border-indigo-100",
    items: [
      { q: "What certificate types can I record?", a: "BDE Farm Trac supports 50+ certificate types across 10 groups: Pesticide Application (PA1–PA6AW), Livestock Welfare (WASK/WATOK, disbudding, AI), Animal Transport (Cat 1 & 2), Machinery (telehandler, FLT, ATV, combine), Chainsaw (CS30–CS38), Health & Safety (FAW, EFAW, COSHH, confined space), Agronomy (BASIS, FACTS, NRoSO), Veterinary & Medicines (AMTRA SQP), Food & Hygiene (Level 2 & 3), and Formal Qualifications." },
      { q: "How does the Right to Work register work?", a: "The staff record includes a Right to Work section where you can record the document type, reference number, check date, and examiner. For time-limited visas, BDE Farm Trac tracks the expiry date and surfaces an urgent alert within 28 days of expiry. The compliance gap panel on the staff list also flags any team member with no Right to Work check recorded." },
      { q: "How do I set up departments and assign staff to them?", a: "Navigate to Departments in the sidebar. Create each department with a name and an optional description — typical examples are Arable, Livestock, Dairy, Maintenance, or Office. Once a department is saved, you can assign any number of staff members to it from the department's member list. Staff can belong to more than one department. The Departments page shows a head-count for each department and a member list; a Former Staff tab shows people who were previously members. Staff selection dropdowns across the platform — task assignment, training records, and other operational forms — show each person's department alongside their name so you can quickly find the right team member. The Task Board and Training Records pages include a department filter so department heads can view only their team's outstanding work. All six Labour Management tabs — Timesheets, Rota & Shifts, Actual Attendance, Holiday & Absence, Pay Summary, and Working Time — display staff grouped by department with a colour-coded left-border section header for each team when departments are configured; if no staff have departments assigned the view falls back to a flat alphabetical list." },
      { q: "Can staff see their own tasks on mobile?", a: "Yes. Staff with mobile app access see a Task Inbox in the app showing all tasks assigned to them. Each card shows the task, due date, module, and any manager's note. Staff can mark tasks as in progress or complete with an optional completion note. Managers see status updates in real time on the Task Board in the dashboard." },
      { q: "What is the Labour Cross-Reference tool and how do I use it?", a: "The Labour Cross-Reference is a dedicated tab on the Labour Management page (Staff & Training → Labour Management → Cross-Reference). It compares the total hours each staff member has logged in their Timesheets against the hours recorded for that person in Field Operations over the same period. Each row shows the staff member's name, their timesheet hours, their field operations hours, and the variance — colour-coded as Matching (green), Over-Reported (amber), or Under-Reported (red). Managers can click the annotation icon on any row to add an explanatory note and mark the discrepancy as Explained or Resolved. Annotated rows display a badge (Explained or Resolved) in the table alongside a preview of the most recent note, so you can see at a glance which discrepancies have been reviewed. Use the month and year selectors to move between periods. This tool helps satisfy Red Tractor's requirement to cross-check labour records against operational records and to document that discrepancies have been investigated." },
      { q: "Can I assign a task directly from a compliance record rather than from the planner?", a: "Yes — this is one of the key traceability features in BDE Farm Trac. A Raise Task button is available on records across multiple modules so that corrective or follow-up actions are always linked back to the compliance event that triggered them. You can raise tasks directly from: an Equipment defect report (the repair task links back to the specific defect); a Risk assessment record (the control-measure task links to the specific hazard); a Medicine withdrawal record (the end-of-withdrawal check is pre-set to the calculated withdrawal end date); a Vet Ledger visit with a follow-up requirement (the follow-up visit task pre-fills the visit reason and target date); a Spray application record (the application is assigned to a named operator); a Feed bin reorder (the reorder task links back to the specific bin); a TB test record (the read-date task is pre-set to the calculated read date); a Contractor H&S review record (the follow-up action task links back to the review); and Work Orders in Farm Services. All tasks raised this way appear on the Task Board tagged with their source module, so managers have a full picture of open actions and their compliance origin in one view. The completed tasks section of the Task Board includes a date filter to review what was done within any selected period." },
      { q: "Where is the PPE Register and how does it work?", a: "The PPE Register lives in the Staff page — click Staff in the sidebar, then switch to the PPE Register tab. It is divided into three linked sub-registers accessible via sub-tabs. The PPE Stock Register records every incoming delivery of protective equipment: select the PPE type, enter a description or specification, size, quantity received, unit cost, and link it to a supplier from your Supplier register (or type a name manually). You can also record the invoice reference, delivery note reference, batch number, and received date for full financial traceability. Once a stock record is saved, the quantity in stock is tracked automatically and displayed in colour-coded form (green when healthy, amber when low, red when out of stock). The PPE Issue Register records every item issued to a named staff member, satisfying the PPE at Work Regulations 2022 requirement for documented individual records. When issuing, you can optionally select a stock batch — this auto-fills the type, description, size, and supplier, and decrements the stock level by one. Each record captures the issue date, condition at issue, condition check dates, and replacement date and reason if the item has been replaced. Every staff member's complete PPE history is visible directly on their profile card. The PPE Risk Assessments sub-tab holds documented risk assessments for each type of PPE in use on the holding, as required under the PPE at Work Regulations 2022. Field staff can also log PPE issues from the mobile app, which queues the record for sync to the dashboard." },
      { q: "What is a PPE Risk Assessment and how do I record one?", a: "The PPE at Work Regulations 2022 require employers to carry out a suitable and sufficient assessment of the risks to health and safety before selecting PPE. In BDE Farm Trac, PPE Risk Assessments are recorded in the third sub-tab of the PPE Register (Staff > PPE Register > PPE Risk Assessments). Each assessment captures: a unique assessment reference, the PPE type being assessed, the hazard identified, the task or work area where the hazard arises, the risk level (Low / Medium / High), whether a fit check has been carried out and by whom, whether compatibility with other PPE has been checked, whether training has been provided, who carried out the assessment, the assessment date, and a next review date. Assessments can be edited and deleted. When a review date passes without an update, the date is highlighted in red to prompt action. The Assessed By and Fit Confirmed By fields accept a typed name or a selection from your registered staff team." },
      { q: "How do I print a PPE Compliance Pack for a Red Tractor inspection?", a: "A Print Compliance Pack button sits to the right of the PPE sub-tab bar and is visible from all three tabs. Clicking it generates a landscape-format PDF covering all three registers in a single document. The report opens with a four-card summary showing the total number of risk assessments (flagging any overdue for review), stock items, active PPE issues (flagging any needing attention or condemned), and the number of PPE types in active use that have no corresponding risk assessment recorded. Below the summary, Section 1 lists all risk assessments with reference, PPE type, hazard, task or area, risk level, fit check, compatibility check, training provided, assessor, assessment date, and review due date — with overdue review dates highlighted in red. Section 2 lists all stock items with supplier, invoice, delivery note, received date, and live stock levels. Section 3 lists the full issue register with staff name, PPE type, description, condition, and status. The report is generated directly in your browser — no file upload required — and is ready to print or save as a PDF." },
      { q: "How do I print an individual staff member's PPE record?", a: "On the PPE Issue Register sub-tab, use the staff member filter dropdown to select the person you want. Once a specific staff member is selected, a Print Staff Record button becomes active next to the filter. Clicking it generates a landscape-format PDF for that person containing two sections: their full PPE issue history (all items ever issued, most recent first, with condition checks and replacement notes) and a table of all PPE risk assessments that cover the PPE types that person has been issued. If there are PPE types the person has received but no risk assessment has been recorded for, the second section displays a prominent warning flag — this directly highlights a compliance gap under the PPE at Work Regulations 2022. The report includes the farm name, CPH number, and a regulatory footer note and is suitable for presenting to a Red Tractor assessor or HSE inspector." },
    ],
  },
  {
    title: "Health, Safety & Risk",
    icon: Flame,
    color: "bg-red-50 text-red-600 border-red-100",
    items: [
      { q: "What does the Health, Safety & Risk module cover?", a: "The Health, Safety & Risk module is found in the dashboard sidebar under 'Health, Safety & Risk'. It is divided into four tabs: Risk Assessments (hazard register with risk level, control measures, review date alerts, and Raise Task integration), COSHH Records (substance register with hazard classification, PPE, and emergency procedures), PAT Testing (Portable Appliance Test log for all electrical equipment), and Fire Safety (fire extinguisher register with per-unit service history). A Print H&S Register button at the top right generates a single landscape-format PDF covering all four areas — suitable for presenting to a Red Tractor assessor or HSE inspector without further preparation." },
      { q: "How do I register a fire extinguisher on the holding?", a: "Go to Health, Safety & Risk in the sidebar and click the Fire Safety tab. Click Add Extinguisher. Select the building or area from the Farm Buildings & Areas picker — this links the extinguisher to your buildings register so it appears under the correct location filter. If you have not set up farm buildings yet, type the location manually. Enter the exact position within the building (for example, 'Near roller door' or 'Left of main entrance') so an engineer can locate it without a floor plan. Select the extinguisher type (CO₂, Dry Powder, Foam, Water, or Wet Chemical), capacity in kg, and serial number. You can optionally record the last service date, next service due date, and servicing engineer at this point — or add these later by logging a service record. Save the record. The extinguisher now appears in the register table on the Fire Safety tab and is included in the print H&S Register." },
      { q: "How do I log an annual service record for a fire extinguisher?", a: "On the Fire Safety tab, find the extinguisher row in the register and click the Service button on the right, or click View to expand the row and then click Log Service. A dialog opens where you record the service date, service type (Annual Check, 5-Year Discharge Test, Interim Check, Extended Service, or Commissioning), engineer name, engineer company (drawn from your Trade Contacts — type a new name to add it inline), certificate number, result (Pass, Advisory, or Fail), and the next service due date. If you select Annual Check or Commissioning, the next service due date is auto-calculated as one year from the service date; for a 5-Year Discharge Test it calculates five years. You can also attach the service certificate PDF to the record. When you save, the parent extinguisher's Last Service Date and Next Service Due fields are automatically updated to match. The service record appears in the expanded service history table under that extinguisher row." },
      { q: "How do I mark a fire extinguisher as disposed or decommissioned?", a: "Open the extinguisher record by clicking the edit (pencil) button on its row. At the bottom of the form, change the Status field from Active to Disposed / Decommissioned. Three additional fields appear: Disposal Date, Disposal Reason (End of life, Failed service, Damaged, Replaced with new unit, or Other), and Disposal Notes. Fill these in and save. The extinguisher row is greyed out in the register table and the service button is disabled — it cannot receive new service records. The record is never deleted; it is retained permanently for audit. In the print H&S Register, disposed extinguishers are listed in a footnote below the active register table showing type, serial number, and disposal date." },
      { q: "What does the print H&S Register include?", a: "Click the Print H&S Register button at the top right of the Health, Safety & Risk page (visible from any tab). A print preview opens in a panel on the page showing the full register formatted for A4 landscape printing. Section 1 covers Risk Assessments — all active assessments listed by risk level (critical first), with hazard, control measures, assessor, and review date; overdue review dates are highlighted in red. Section 2 covers COSHH Records. Section 3 covers PAT Testing — all registered items with tester, certificate, result, and next due date; overdue dates are highlighted. Section 4 covers the Fire Extinguisher Service Register — all active extinguishers with location, position, type, capacity, serial number, last service date, engineer, company, and next service due; overdue dates are highlighted in red. Disposed extinguishers are listed in a footnote. Click Print / Save PDF to send it to your browser's print dialog where you can save as a PDF or print directly." },
      { q: "How does fire extinguisher servicing link to the Farm Planner?", a: "When you record a Next Service Due date on a fire extinguisher, BDE Farm Trac automatically surfaces this in the Week Ahead and Month Ahead planner as an upcoming task. Within 60 days of the service due date, an amber warning appears on the extinguisher row in the register. Once the date passes without a service record being logged, the warning turns red (Overdue) and an overdue count is displayed at the top of the Fire Safety tab. You can click the planner task entry to go directly to the extinguisher record. This ensures service dates are never missed without needing a separate calendar or reminder system." },
      { q: "How do I record a COSHH assessment for a substance?", a: "Navigate to Health, Safety & Risk and select the COSHH Records tab. Click Add Record. Enter the substance or product name, hazard classification (Flammable, Corrosive, Toxic, Irritant, Harmful, Environmental Hazard, or Other), storage requirements, PPE requirements for handling, emergency procedures, and a mandatory review date. COSHH records with a review date approaching within 60 days display an amber warning; overdue reviews turn red. The COSHH section is included in the print H&S Register alongside risk assessments, PAT, and fire safety." },
      { q: "How does PAT testing work and what regulations does it cover?", a: "Go to Health, Safety & Risk and select the PAT Testing tab. Click Add PAT Record to log each piece of electrical equipment. Record the item name, make and model, location, tester name, tester company, certificate number, test date, result (Pass, Fail, or Advisory), and next due date. Every appliance is automatically assigned a unique BDE-PAT-XXXX asset code when the record is created — shown as a violet badge on each row. Click the QR icon on any row to print a label card for that appliance; the card contains a scannable QR code, the BDE-PAT-XXXX code, the appliance name, make and model, and a prompt to scan with the BDE Farm Trac app. Affix the label to the appliance. A visiting PAT tester or farm staff can then open the mobile app, scan the label, and tap Record PAT Test to log the result directly — the form pre-fills with today's date and a next-due date 12 months ahead. The register shows all items with colour-coded next-due alerts. Under the Electricity at Work Regulations 1989, employers must maintain electrical equipment in a safe condition — PAT testing is the practical way to evidence this. The PAT section of the print H&S Register lists all items with asset code, tester, certificate, result, and next due date in a format suitable for an HSE or Red Tractor assessor." },
    ],
  },
  {
    title: "Finance & Reports",
    icon: LineChart,
    color: "bg-emerald-50 text-emerald-600 border-emerald-100",
    items: [
      { q: "Does BDE Farm Trac connect to my accountancy software?", a: "BDE Farm Trac is not an accountancy package — it is a farm management and compliance record system. Financial records (purchase invoices, sales records, grant payments) are logged here for Red Tractor traceability and farm business planning. You can export records as CSV for import into Xero, QuickBooks, Sage, or similar." },
      { q: "Can I record Basic Payment / SFI payments?", a: "Yes. The Finance & Business module includes a subsidy and grant register where you can record SFI agreement payments, Countryside Stewardship, and other scheme income. Historic BPS payments can also be logged for year-on-year comparison." },
      { q: "How do I record purchase invoices?", a: "Navigate to Finance > Purchases. Log each purchase with supplier, invoice number, date, category, net amount, VAT, and any relevant field or livestock link. Recurring suppliers are remembered from your Supplier Register, saving data entry time. For livestock purchase invoices specifically, the form includes a Movement Record section where you can link the invoice directly to its corresponding on-holding movement record — creating a complete audit trail from invoice to BCMS or AML reference." },
      { q: "How do I track grain forward contracts and pool scheme positions?", a: "Open the Finance & Business page on the dashboard and select the Grain Contracts tab. Forward contracts show the merchant, commodity, crop year, agreed price, and a progress bar displaying called-off tonnage against the total committed. Each card expands to list every grain sale linked to that contract, so you can see exactly which loads have been called off. Pool scheme positions are shown separately and track the merchant, commodity, estimated outturn tonnage, and settlement status. When you record a grain sale, you can optionally link it to an open forward contract — the called-off figure updates automatically." },
      { q: "How do I link a grain sale to a forward contract as a call-off?", a: "Open the Finance & Business page on the dashboard and go to the Grain Sales tab. Click Record Grain Sale (or edit an existing sale). Set the Sale Type to 'Forward Contract'. A Linked Forward Contract dropdown immediately appears listing all your open contracts for that farm. Select the contract this load is being called off against — the dropdown shows the contract reference, buyer, commodity, and committed tonnage so you can identify it quickly. Save the record. The grain sale row in the table shows a green Contract badge, and the forward contract card on the Contracts tab updates its called-off progress bar and remaining tonnage in real time. If the dropdown is empty, first add the contract on the Contracts tab — you need at least one forward contract record before you can link a call-off against it. On the mobile app, record the sale with Sale Type set to Forward Contract and note the contract reference in the Forward Contract Reference field; the database link is then completed when you edit the record on the dashboard after it has synced." },
      { q: "What happens when I deactivate a supplier or contact?", a: "BDE Farm Trac never physically deletes any supplier, buyer, or trade contact record — instead, contacts can be marked as inactive (deactivated) when a relationship ends. All historical records, purchase history, delivery logs, and declarations linked to that contact are preserved in full and remain accessible. A deactivated contact is shown with an Inactive badge in the register and is excluded from active dropdowns so it does not appear as an option when logging new transactions. You can reactivate a contact at any time if the relationship resumes. This design ensures your audit trail is never broken." },
    ],
  },
  {
    title: "Parts Store & Stock Management",
    icon: Package,
    color: "bg-orange-50 text-orange-700 border-orange-100",
    items: [
      { q: "How do I log an equipment defect?", a: "Open Equipment & Workshop and go to the Defect Reports tab on any equipment record, or view all defects across the fleet from the main Equipment page. Click Raise Defect, select the piece of equipment, choose a severity level (Low, Medium, High, or Critical), and describe the fault. High and Critical defects display a warning banner on the equipment record flagging it as potentially unsafe to operate until resolved. Status moves through Open → In Progress → Resolved, with an audit trail of who updated each step and when. At any point you can click Raise Task on the defect to assign the repair to a named staff member — the task pre-fills the defect reference and equipment name and appears on the Task Board for tracking." },
      { q: "How does the Workshop Parts Store stocktake work?", a: "Open the Workshop page and navigate to the Parts Store tab, then click the Stocktake button in the navigation. The stocktake view lists every part in your parts store with its current system stock quantity. Enter your physical count for each item directly in the count column. Any variance — where your physical count differs from the system — is shown in a coloured badge (red for over-count, orange for under-count, green for zero variance). A summary bar at the top tracks how many items you have checked and whether all variances have been reviewed. When you click Complete Stocktake, a confirmation dialog is shown and all stock levels are updated in one step to match your physical counts." },
      { q: "How does the main stock stocktake work on Suppliers & Stock?", a: "Go to Suppliers & Stock and select the Stocktake tab. The system presents a count sheet of all stock items registered in your main stock register. Enter your physical count for each item. Items with a variance — where the physical count does not match the system quantity — display a colour-coded badge and require you to select a reason for the discrepancy before the stocktake can be completed. The available reason codes are: Calibration (measuring error), Spillage or wastage, Theft or loss, Data entry error, or Other. This is a Red Tractor requirement — every discrepancy must be explained and documented. Once all variances have been assigned a reason, clicking Complete Stocktake updates all stock levels and writes a permanent stock movement record for each adjusted item, creating a full audit trail suitable for a Red Tractor or internal stock audit." },
      { q: "Why does the main stock stocktake block completion until I select a reason for each variance?", a: "Red Tractor standards require that any unexplained difference between a recorded stock level and a physical count is documented with a reason. BDE Farm Trac enforces this at the point of completing a stocktake — you cannot finalise the count until every item showing a variance has a documented reason selected. The available reasons (calibration, spillage, theft, data entry, other) match the categories used in most farm assurance scheme audits. The selected reason is stored permanently against the stock movement record created when the stocktake is completed." },
      { q: "Can I run a stocktake without affecting stock levels for items I did not count?", a: "Yes. Items where you have not entered a physical count (the count field is left blank) are skipped when the stocktake is completed — their stock levels are not changed. This means you can run a partial stocktake, counting only selected items and leaving others unchanged. Only items where you have entered a physical count will have their stock levels updated." },
    ],
  },
  {
    title: "Farm Shop & Diversification",
    icon: Store,
    color: "bg-violet-50 text-violet-700 border-violet-100",
    items: [
      { q: "How does farm shop stock management work?", a: "Each farm shop product has a selling price, cost price, unit, and reorder level. When you record a sale, the product's stock quantity decrements automatically. When you log a purchase delivery from a supplier, stock increases. The live quantity on hand is always visible in the Products tab so you know exactly what is available to sell." },
      { q: "What is the margin column and how is it calculated?", a: "The margin column in the Products table shows the percentage gross margin for each item — calculated as (selling price minus cost price) divided by selling price. It is colour-coded: green for a healthy margin, amber when margin is tight (below around 20%), and red if the product is priced below cost. If no cost price has been entered, the margin column is blank. You can set or update the cost price at any time, or tick 'Update cost price' when recording a purchase to keep it current automatically." },
      { q: "How do I receive low-stock alerts for farm shop products?", a: "Set a reorder level on each product in the Products tab. When a sale brings the stock quantity to or below that level, an in-platform low-stock notification is created automatically. If you have the SMS Text Alerts add-on active, an out-of-stock event (stock reaching zero) will also send a text message to your registered number so you can reorder immediately." },
      { q: "Can I link purchases to specific farm shop suppliers?", a: "Yes. The Suppliers sub-tab within the Farm Shop module lets you maintain a directory of the businesses you buy stock from. When recording a purchase in the Purchases ledger, you select the supplier from this directory — the supplier name is stored with the purchase record for a complete audit trail. Suppliers who are no longer used can be deactivated rather than deleted, preserving all historic purchase records." },
      { q: "Can I update the cost price of a product when I receive stock at a new price?", a: "Yes. When logging a purchase in the Purchases ledger, tick the 'Update cost price' checkbox before saving. This automatically overwrites the product's stored cost price with the unit cost from that purchase. The margin column will recalculate immediately, keeping your profitability data current without any manual edits to the product record." },
      { q: "Can I record food hygiene inspection results including the FHRS rating?", a: "Yes. The Hygiene Inspections tab in the Farm Diversification module lets you log every formal inspection and audit. The 'Relates To' field lets you specify which part of your diversification enterprise the inspection covers — Farm Shop, Food Processing, Events/Catering, Farm Kitchen, Equine/Livery, or Other. The Inspection Type covers Local Authority Routine, Allergen Compliance, HACCP Audit, Red Tractor, Self-Audit, and Other. The Food Hygiene Rating is recorded on the 0–5 FHRS scale with a colour-coded descriptor (Urgent Improvement Necessary through to Very Good). You can flag whether a reinspection is required, set the target reinspection date, and document findings and corrective actions. These records are also available on the mobile app for staff completing self-audits on site." },
      { q: "How do I log equine health events such as vaccinations and farrier visits?", a: "Equine health events are recorded in the Equine section of the Farm Diversification module on both the dashboard and the mobile app. For each event, record the horse name, event date, and event type — Vaccination, Worming, Farrier, Dental, Vet Visit, Passport Check, or Other. For vaccinations and worming treatments, additional fields appear for the product name, batch/lot number, and next due date, providing the traceability required for equine passports and vet audit records. The attending vet or farrier's name, treatment given, cost, and any notes are also recorded." },
      { q: "How do I record a shoot day and log the bag count?", a: "Open the Shooting & Game section in the Farm Diversification module and log each shoot day separately. Record the shoot date, shoot type (Formal Driven, Rough Shoot, Walked-Up, Pigeon, Wildfowl, or Other), organiser, number of guns, and gamekeeper. The bag count section has individual fields for Pheasant, Partridge, Grouse, Duck, Woodcock, and Other — the total bag calculates automatically as you enter figures. You can also record the game dealer and any income or lease fee received for the day. These records are available on the mobile app so gamekeepers can log the day in the field." },
    ],
  },
  {
    title: "Poultry Production",
    icon: Bird,
    color: "bg-amber-50 text-amber-700 border-amber-100",
    items: [
      { q: "How do I set up the Poultry Production module?", a: "Navigate to Poultry Production from the main menu. Start by creating your houses in the Houses tab — record the house number or name, species, production system (broiler, free-range, organic, layer, etc.) and floor area. Next, register each flock placement in the Flocks tab: enter the flock number, select the house, choose the species, record the breed or strain, enter the placement date and the number of birds placed, and add the hatchery name and approval number for traceability. Each flock record becomes the parent for all mortality, treatment, welfare check, and thinning records associated with that placement. Once your first flock is registered, you can begin logging daily mortality records immediately." },
      { q: "How does the daily mortality log work and what does Red Tractor require?", a: "Open Poultry Production and go to the Mortality tab. Each day you record the number of birds found dead (natural mortality) and the number culled, select the flock, and choose the main cause from the cause classification list. The system calculates a running total and cumulative mortality percentage for the flock automatically — you do not need to enter these manually. Red Tractor Broiler standards require daily mortality records to be kept for a minimum of three years. The mortality tab includes a year filter so you can view and export records for any specific year, and a compliance reminder is shown at the top of the tab." },
      { q: "How does the year-by-year mortality trend work?", a: "Once you have mortality data spanning more than one calendar year, a Year-by-Year Mortality Trend table appears automatically in the summary panel on the Mortality tab. It shows each year with the number of distinct crops (flocks) that had records, total deaths, total culled, and the peak cumulative mortality percentage reached in any crop during that year. A colour-coded bar chart visualises the trend: green indicates peak mortality below 3%, amber 3–5%, and red above 5% — aligned with the thresholds Red Tractor assessors use when reviewing flock performance. The year filter at the top right of the tab lets you narrow the summary stats, flock breakdown, and data table to a specific year while the trend table always shows all years for comparison." },
      { q: "What is the hatchery / supplier mortality breakdown?", a: "If your flocks have been placed from more than one hatchery or chick supplier, BDE Farm Trac automatically groups mortality data by hatchery name and shows a By Hatchery / Supplier breakdown table in the mortality summary panel alongside the breed breakdown. For each hatchery it shows the number of crops placed, total deaths, total culled, and the peak cumulative mortality percentage — colour-coded green (below 3%), amber (3–5%), or red (above 5%). This gives you hard, objective evidence when comparing suppliers: if Hatchery A consistently delivers crops that peak below 2% and Hatchery B regularly reaches 4–5%, that pattern will show clearly over time. It is useful evidence when negotiating with a supplier, when raising a quality complaint, or when a vet or Red Tractor assessor asks how you are monitoring chick quality. To enable this breakdown, ensure the Hatchery Name field is completed on each flock record in the Flocks tab — it is the same field used for Red Tractor hatchery traceability. Flocks with no hatchery name recorded show as 'Not recorded'." },
      { q: "What is the breed and strain mortality breakdown and how do I use it?", a: "If your flocks use different breeds or strains — for example Ross 308 alongside Cobb 500, or standard commercial breeds alongside slower-growing breeds for higher-welfare or organic schemes — BDE Farm Trac automatically groups mortality data by breed and shows a By Breed / Strain breakdown table within the mortality summary panel. For each breed it shows the number of crops placed, total deaths, total culled, and the peak cumulative mortality percentage. This makes it straightforward to identify whether one breed consistently suffers higher mortality than another — useful evidence for discussions with your vet, nutritionist, or hatchery, and for demonstrating to a Red Tractor assessor that mortality patterns are being monitored and investigated at the breed level. To enable this breakdown, ensure the Breed / Strain field is completed on each flock record in the Flocks tab. Flocks with no breed recorded show as 'Not recorded'." },
      { q: "What cause classifications are available for poultry mortality?", a: "The mortality cause list covers the main causes recognised in commercial poultry production: Natural causes (normal losses), Sudden Death Syndrome (SDS / Flip-over), Ascites (Waterbelly), Cardiovascular failure, Respiratory disease, Leg / skeletal problems, Digestive disorder, Bacterial infection, Viral disease, Injury / trauma, Cannibalism / pecking injury, Heat stress, Chilling (young chicks), Smothering / piling, Nutritional deficiency, Unknown, and Other (specify in notes). The same list is used on both the dashboard and the mobile app. Reviewing the cause distribution over time can highlight patterns that require investigation — for example a rise in Ascites cases may point to ventilation or growth rate issues, while an increase in leg problems may relate to litter quality or genetics." },
      { q: "Can I record poultry mortality on the mobile app?", a: "Yes. Open the mobile app and tap Daily Mortality from the Poultry section of the Record screen. Select your flock, enter the date, the number of dead birds, and the number culled. Tap the cause chip to record the main cause of death. The record is saved locally and synced to the dashboard when you next have connectivity. Running totals and cumulative mortality percentages are calculated server-side when the record syncs — they are not shown in real time on the mobile app but will appear on the dashboard once synced." },
      { q: "How does the Poultry module link to Red Tractor Poultry standards?", a: "The Poultry Production module is structured around the core Red Tractor Poultry audit areas. Flock records provide the traceability chain from hatchery to depletion. Daily mortality records with cause analysis satisfy the requirement for systematic mortality monitoring and trigger-level checking. Medicine and vaccine records with withdrawal period tracking meet the medicine recording requirements. Welfare daily checks satisfy the Welfare of Farmed Animals (England) Regulations record-keeping requirements. Biosecurity checklists, downtime records between placements, and Salmonella NCP test results all map to specific Red Tractor checklist items. The scheme records tab within the module lets you record assessor visit outcomes and any non-conformances raised." },
      { q: "How do I record a house cleanout and what information does it capture?", a: "Open Poultry Production and go to the Cleanouts tab, then click New Cleanout Record. The form captures who carried out the cleanout — toggle between Farm Staff and Contractor. For farm staff, record who completed the cleanout and who verified it. For contractors, record the company name and whether they supplied their own materials. The Primary Disinfectant section captures the DEFRA-approved disinfectant used, its approval number (from the Defra approved disinfectants list), the dilution rate applied, contact time, and standing time before restocking — the core fields a Red Tractor assessor or Salmonella NCP auditor will look for. If your own stock was used, you can log each product consumed by quantity, which feeds directly into your stock levels. For contractor jobs, you can record the cost in pence and an invoice or purchase order reference. Swab testing results (pre-clean environmental swabs) can be recorded, and photo evidence of the cleaned and disinfected house can be attached. The Cleanouts tab shows a summary of total cleanouts completed, how many were done by contractors, and total contractor cost for the period." },
      { q: "Can I record a house cleanout biosecurity checklist on the mobile app?", a: "Yes. Open the mobile app and tap Poultry Cleanout Biosecurity from the Poultry section of the Record screen. The mobile form is designed for use during the physical cleanout process — it walks you through all 14 biosecurity steps (litter removal, dry clean, pre-wash, main wash, disinfection, contact time, fumigation, vermin control, water system, feed system, footbaths, biosecurity signs, change room, and egg equipment). Toggle whether the cleanout is being done by farm staff or a contractor and enter the contractor name if applicable. Record who completed the cleanout and who verified it, the primary disinfectant used and its approval number, the dilution rate, contact time, and downtime in days. The progress bar at the top shows how many steps have been ticked off. The record is saved locally and synced to the dashboard when you next have connectivity." },
    ],
  },
  {
    title: "Biofuel / RTFO",
    icon: Fuel,
    color: "bg-yellow-50 text-yellow-700 border-yellow-100",
    items: [
      { q: "What is the RTFO and who does it apply to?", a: "The Renewable Transport Fuel Obligation (RTFO) is the UK government scheme that requires transport fuel suppliers to blend a proportion of renewable (biofuel) content into the fuel they sell. If you grow OSR, wheat, or other qualifying crops and sell them to an obligated fuel supplier for processing into biofuel, your buyer needs RTFO-compliant sustainability data — including field eligibility records, GHG traceability information, and a signed sustainability declaration from you as the grower. BDE Farm Trac's Biofuel / RTFO module is designed to generate and maintain exactly that documentation." },
      { q: "What is an RTF Obligation Number and where do I find it?", a: "An RTF Obligation Number is the Department for Transport reference number issued to each obligated fuel supplier (your biofuel buyer). It uniquely identifies the buyer in the RTFO system and must appear on every sustainability declaration you issue to them. Your buyer should be able to provide this number. Enter it into their record in the RTFO Buyers register — it will then auto-populate on all sustainability declarations for that buyer." },
      { q: "How do I record a biofuel crop delivery?", a: "Go to the Biofuel / RTFO page and open the Deliveries tab. Click New Delivery and fill in the date, buyer (selected from your Registered Buyers list), field or fields supplying the crop, quantity, vehicle or haulier details, and the sustainability declaration reference your buyer issues you. This creates a permanent, audit-ready record of every consignment your buyer can reference in their RTFO return." },
      { q: "What GHG data does BDE Farm Trac supply for biofuel compliance?", a: "The Biofuel / RTFO overview page automatically counts the number of NVZ fertiliser applications and spray applications recorded in your other modules for RTFO-eligible fields. Your ISCC auditor or biofuel buyer uses these figures to calculate a field-level GHG footprint that must accompany the sustainability declaration. You do not need to enter data twice — it is drawn directly from your existing NVZ and Sprays records." },
      { q: "What happens to historic sustainability declarations if I stop working with a buyer?", a: "You can deactivate a buyer in the RTFO Buyers register rather than deleting them. The buyer is marked Inactive and no longer appears in the dropdown when logging new deliveries — but every historical delivery and sustainability declaration linked to them is preserved in full on your record. Reactivate them at any time if the relationship resumes." },
    ],
  },
  {
    title: "Grain & Crop Storage",
    icon: Warehouse,
    color: "bg-amber-50 text-amber-700 border-amber-100",
    items: [
      { q: "What storage location types does BDE Farm Trac support?", a: "You can register any of the following location types: grain store, silo, general storage, ambient warehouse, cold store, chemical store, fertiliser store, and merchant or elevator position (for grain held off-farm with a merchant). Each location holds the commodity, variety, maximum capacity, and GPS coordinates. You can create as many locations as you need across your holding." },
      { q: "What types of stock movements can I record?", a: "BDE Farm Trac covers all the movement types that arise in grain and crop storage: Intake (crop coming into the store from harvest or delivery), Dispatch (crop leaving the store for sale or transfer), Transfer In and Transfer Out (internal movements between two locations on the same farm), Sample Withdrawal (a sample taken and not returned — treated as a stock reduction), Drying Loss (moisture-driven weight reduction), and Manual Adjustment (a catch-all for stock corrections where direction is free to set as in or out)." },
      { q: "How does the stock balance work?", a: "The balance is calculated in real time from all movements recorded against a location. Three summary cards show Total In, Total Out, and the current Balance (In minus Out) in tonnes, to three decimal places. If you apply the year filter, the summary cards update to show only the movements within the selected year — useful for calculating a crop-year's net position or reconciling against a merchant statement." },
      { q: "Can I link a stock movement to a haulage record, grain sale, or harvest record?", a: "Yes. Every stock movement has an optional 'Link to existing record' section in its dialog. Select the record type (Haulage Record, Grain Sale, or Harvest Record) and then pick the specific record from a dropdown. The movement table shows a clickable reference chip for any linked movement — clicking it opens a details panel showing the full record: weighbridge ticket number, date, tonnage, buyer, field, crop, grade, and more. This creates a complete chain of custody from harvest through store to sale, all navigable within a single screen." },
      { q: "What are merchant storage charges?", a: "If you store grain off-farm with a merchant or elevator, they will periodically charge you for storage, drying, cleaning, and handling. The Merchant Storage Charges tab (shown on merchant-type locations) lets you log each charge with a date, charge type, description, quantity (tonnes stored), rate, and total amount. The table includes a year filter so you can see charges for a specific crop year, and a total footer shows the sum for the selected period — making it straightforward to cross-check against your merchant statements." },
      { q: "How do I record a Grain Store or Crop Stock stocktake?", a: "Open the Grain Store page on the dashboard and navigate to the Stocktakes tab. Click Record Stocktake to open the dialog. Select the storage bin or location from the dropdown, then enter the physical quantity in tonnes as measured during your count. The system quantity auto-fills from the running stock balance for that location — the variance (physical minus system) is calculated immediately and shown as a colour-coded badge (green for zero variance, amber for a surplus over system stock, red for a shortfall). Choose the measurement method: Probe Measurement, Auger Sample, Weighbridge, or Visual Estimate. Enter who conducted the stocktake and confirm the date. Add any notes about the count conditions or the reason for the discrepancy. Click Save — the record is written to the stocktake history for that location and is visible in the table immediately. On the mobile app, tap 'Grain Store Stocktake' in the Record tab; the bin picker, system quantity auto-fill, variance badge, and measurement method selection all work the same way offline and sync to the dashboard when connectivity is restored." },
    ],
  },
  {
    title: "Farm Services & Contracting",
    icon: Wrench,
    color: "bg-cyan-50 text-cyan-700 border-cyan-100",
    items: [
      { q: "What is the Farm Services & Contracting module for?", a: "Many farms earn income by providing services to neighbouring farms and landowners — combine harvesting, drilling, baling, spraying, hedge cutting, or hiring out machinery. The Farm Services & Contracting module lets you record all of these activities in one place: define your service types, maintain a customer directory, log every job with dates and values, track equipment hire with booking references, record grain intake for third parties, and view a revenue summary by service type and customer. It is designed for farms that act as a service provider in addition to their own production activities." },
      { q: "What are the summary stats bars at the top of each Farm Services tab?", a: "Each tab in the Farm Services module — Agreements, Equipment Hire, Grain Intake, Work Orders, and Invoices — opens with a row of four summary cards showing live totals and status counts without needing to scroll through records. For example, the Equipment Hire tab shows active hires today, bookings this month, total hire value this month, and insurance warnings requiring attention. The Invoices tab shows total invoiced, amount outstanding, and count by payment status. These figures update automatically as records are added or changed." },
      { q: "Does BDE Farm Trac keep records of customers I no longer work with?", a: "Yes. The Farm Services customer directory uses the same soft-delete principle as the rest of BDE Farm Trac — no record is ever permanently deleted. If a customer relationship ends, you mark the customer as inactive. They disappear from active dropdowns so they cannot be selected for new jobs, but every historic job record linked to them remains fully accessible and intact on your account. You can reactivate them at any time if the relationship resumes." },
      { q: "How does the insurance cross-reference work?", a: "When you log a farm service job or book equipment hire, BDE Farm Trac checks the job date against the expiry dates of the insurance policies registered in your Insurance Register (specifically Public Liability and Employer Liability). If a job falls outside a policy period, a warning is flagged so you can review your cover before the work begins. This helps ensure you are not carrying out commercial contracting activities while underinsured." },
      { q: "What are Work Orders and how do I use them?", a: "Work Orders are task assignments specifically for contract or service work — every work order is assigned to a named staff member and automatically appears on their Task Board card list and in the Week Ahead planner on the scheduled date, with an SMS notification sent immediately. You can raise a work order two ways. First, go to Farm Services > Work Orders tab and click New Work Order: enter the work description, select a staff member (required), optionally link a customer from your Customer Directory, set a scheduled date and estimated hours. Second, when creating a service invoice you can toggle the Schedule a Work Order panel — this creates the work order at the same time as the invoice and links them together for billing traceability. Work orders show an auto-generated WO- reference and track status through Open → In Progress → Completed. The invoice reference is stored against the work order so you can trace from job completion through to payment in one view." },
      { q: "How does Equipment Hire booking work?", a: "Each hire booking is created from Farm Services > Equipment Hire tab. The system automatically generates a unique booking reference in HIRE-YYYY-NNNN format (for example, HIRE-2025-0004) when you save a new booking. You record the customer, machine being hired, operator (selected from your Staff register), hire start and end dates, agreed daily or hourly rate, and deposit received date. A return condition field is available when closing the booking. The insurance verification flag turns red if the hire period falls outside your registered public liability or employer liability policy dates, prompting you to review your cover before the machine goes out." },
      { q: "What is the Job Reference field on a hire booking?", a: "The Job / Operation Reference is a free-text field that lets you label multiple hire bookings as part of the same job. For example, if you are hiring out a combine, two grain trailers, and a chase bin for the same harvest operation, you would create separate bookings for each machine but give all of them the same job reference — 'August combining — South Block', for instance. That label then appears as a subtitle under each booking reference in the hire list, making it immediately obvious which machines are working together without opening each booking individually. You can also link a booking to a specific registered field using the Linked Field dropdown, which draws from your Fields & Crops register." },
      { q: "What is the Grain Intake tab used for?", a: "The Grain Intake tab records grain deliveries that you accept into your store on behalf of third-party customers — for example, if you operate a commercial grain store and neighbouring farms deliver to you. Each intake record captures the customer, weighbridge ticket number, crop type and variety, load date, moisture percentage, specific weight, grade, load count, and total tonnage. The Grain Intake summary cards at the top of the tab show total loads received, total tonnes in store for the selected period, average moisture across all loads, and total intake value — giving a quick position statement before you look at the individual records." },
      { q: "Can I raise an invoice directly from a Workshop job card?", a: "Yes. When logging a workshop job for work carried out on behalf of a neighbouring farm or customer, select the customer from the Customer dropdown in the job form — your active Farm Services & Contracting customers appear in the list. Once the job status is set to Completed, a Raise Invoice button appears at the bottom of the job card. Clicking it automatically builds a draft invoice in Farm Services & Contracting: a labour line is included based on the hours logged on the job, plus a separate line item for every part issued from the Parts Store against that job. The invoice number is stored back against the job card and displayed as a green badge on the card so you can see at a glance which jobs have been billed. The draft invoice appears in the Invoices tab under Farm Services & Contracting where you can review, adjust, and send it to the customer." },
      { q: "What happens if I have no customers set up yet when trying to link a Workshop job?", a: "The Customer dropdown on the Workshop job form will only show active customers from your Farm Services & Contracting customer directory. If no customers have been added yet, the dropdown will show only the 'None — internal job' option. To add customers, navigate to Farm Services & Contracting and open the Customers tab, then click New Customer to create your first entry. Once saved and set to active, that customer will appear immediately in the Workshop job form dropdown." },
    ],
  },
  {
    title: "Fields & Crops",
    icon: Map,
    color: "bg-emerald-50 text-emerald-700 border-emerald-100",
    items: [
      { q: "What is non-crop land use recording and why does it matter?", a: "Non-crop land use recording lets you document what a field is being used for in seasons when no cash crop is grown — for example, fallow, Sustainable Farming Incentive (SFI) actions, Countryside Stewardship options, permanent grassland, temporary grass leys, woodland and agroforestry, unharvested cover crops, or rewilding areas. Red Tractor requires a complete field rotation record covering every season, not just cropped years. Without this, fields that are left fallow or entered into an agri-environment scheme create unexplained gaps in your rotation history that an assessor may flag. By recording the land use type and any scheme details, BDE Farm Trac produces a continuous, compliant rotation history across all your fields." },
      { q: "What land use types can I record?", a: "BDE Farm Trac supports the following non-crop land use categories: Fallow (bare uncropped ground), Temporary Grass Ley (short-term grass in rotation), Permanent Grassland (established pasture not in the arable rotation), SFI Action (Sustainable Farming Incentive — records the specific action code such as CSAM1, CNUM2, SAM3 etc. and your SFI agreement reference number), Countryside Stewardship (records the CS option code such as AB8, GS8, HK6 etc. and your CS agreement reference), Cover Crop — Unharvested (a living mulch or overwinter cover left in the ground), Woodland / Agroforestry (trees or agroforestry systems on the parcel), and Other — with a free-text notes field for anything that does not fit the above categories." },
      { q: "How do I record a non-crop land use for a field?", a: "From the Fields tab, find the field card. If the field has no crop assigned for the current season, you will see a 'Record land use' button alongside the 'Assign a crop' button at the bottom of the card. Click it to open the Land Use dialog. Select the land use type, the season (Spring, Summer, Autumn, Winter, or Full Year), the crop year, and optionally a start and end date. For SFI and Countryside Stewardship land uses, two additional fields appear: Action / Option Code and Agreement Reference — fill these in so the scheme detail is captured alongside the rotation record. You can also reach this form from the field detail drawer: open any field card, go to the Overview tab, and click 'Record land use' from the Non-Crop Use panel. Once saved, the field card shows a coloured badge identifying the land use type and the Crops Register tab shows the record in the Non-Crop Land Use section at the bottom." },
      { q: "Can I record SFI and Countryside Stewardship scheme details against a field?", a: "Yes. When you select 'SFI Action' or 'Countryside Stewardship' as the land use type in the Land Use dialog, two additional fields appear: Action / Option Code (for example CSAM1, AB8, GS8) and Agreement Reference (your scheme agreement number). These are optional for other land use types but are shown automatically when the selected type is an agri-environment scheme. Recording the action code and agreement reference means your rotation history is audit-ready — an assessor or scheme monitor can see not only that the field was out of crop production, but which specific scheme option applied and under which agreement." },
      { q: "How does the SFI / ELM agreement and action workflow work in BDE Farm Trac?", a: "BDE Farm Trac manages SFI and CS records with a two-level structure — Agreements and Actions — because that reflects how the RPA issues them. An Agreement is the contract itself (with an RPA reference number, scheme name, start and end dates, and total annual payment). An Action or Option (for example SAM1, AB8, WBD6) is a specific land management commitment within that agreement, with its own land parcel, eligible area, payment rate, evidence requirements, and compliance status. Because every action belongs to an agreement, the Add Action button on the SFI / ELM page is disabled until at least one agreement is in place. When you add an action, the Agreement field is the first required field — select which agreement the action falls under before completing the rest of the form. The Actions table shows the agreement reference and scheme name on every row so you can see at a glance which agreement each action belongs to." },
      { q: "What is the recommended way to start a new SFI or CS agreement in BDE Farm Trac?", a: "The recommended route is via Grants & Funding. When an SFI or CS application in the Grants & Funding register reaches Approved status, enter the RPA agreement reference number in the RPA Agreement / Approval Reference field on the grant record — then click the green Start SFI / ELM Record → button that appears. BDE Farm Trac takes you straight to the SFI / ELM page with the Add Agreement dialog pre-filled with the reference number, scheme name, and managing body from your grant record. You only need to add the start and end dates. Once the agreement is saved, open the Actions / Options tab and add each action code from your agreement letter — the agreement field is pre-selected if you have only one agreement on file. For agreements that pre-date BDE Farm Trac or that were not tracked through Grants & Funding, use the Add Agreement button directly on the SFI / ELM page." },
      { q: "Can I record a land use for a past season?", a: "Yes. The Land Use dialog includes a Year field that defaults to the current crop year but can be set to any previous year. This means you can backfill historical records for fields that were fallow or under agri-environment scheme management in previous seasons, filling gaps in your rotation history retroactively. The field detail drawer Season History tab and the printable Field Rotation Register will reflect all years once the records are saved." },
      { q: "Where do I see land use records in the Field Use Register?", a: "The Crops Register tab in Fields & Crops shows two sections. The upper section lists all crops grouped by species and variety with their assigned fields, exactly as before. Below that, a Non-Crop Land Use section appears automatically whenever any land use records exist for the selected year. It shows a table with the field name, land use type badge, scheme action code and reference (if applicable), season, and area in hectares. You can click Edit on any row to update the record directly from the table. The printable Field Use Register (accessed via 'Print register' at the top of the Fields page) produces a combined A4 landscape document covering all fields for all seasons — showing crop assignments, land use records, and any fields with no record at all, giving a complete rotation audit trail." },
      { q: "What are the coloured badges on field cards?", a: "Each field card in the Fields tab shows a small coloured badge in the card header when the field is held under a tenancy, licence, or other non-owned arrangement. The badge colour indicates the type of arrangement: amber for a Farm Business Tenancy (FBT) or Agricultural Holdings Act (AHA) tenancy; violet for a contract farming agreement; sky-blue for a grazing licence; blue for a seasonal licence; and grey for any other arrangement. Fields held as owned freehold show no badge at all — the absence of a badge means the land is owned outright and there is nothing to flag. The badges are there so you can see at a glance, across the whole card grid, which parcels carry rent or licence obligations and what kind of agreement governs them — before you open any individual field." },
      { q: "What is the Land Tenure Register?", a: "The Land Tenure Register is a dedicated tab within Fields & Crops that records the ownership and occupation basis of each field parcel. For each field you can record the tenure type (Owned Freehold, Owned Leasehold, Farm Business Tenancy, Grazing Licence, Seasonal Licence, Share Farming, or other), the landlord or licensor name, annual rent or licence fee, rent review date, and the agreement start and expiry dates. A summary stats bar at the top of the tab shows your total farm area split by owned, tenanted, and licensed land, plus a blended average rent per hectare across all rented and licensed parcels." },
      { q: "How do Land Tenure alerts work?", a: "BDE Farm Trac automatically monitors the rent review dates and agreement expiry dates you have recorded in the Land Tenure Register. Amber alert banners appear when a rent review is due within 90 days or an agreement is expiring within 60 days. Red banners appear when a licence or agreement has already lapsed. Each banner shows the field name, area, tenure type, and the relevant date, and includes an Open button that takes you directly to that field's Tenure tab so you can review and update the record straight away." },
      { q: "How do I add or edit land tenure for a field?", a: "The Land Tenure tab in Fields & Crops shows two sections: the rented and licensed fields register at the top, and a 'No tenure recorded' panel at the bottom listing every field that hasn't had a tenure type set yet. Click the 'Set tenure' button on any field in that lower panel to go straight to the tenure form for that field — it opens ready to edit so you can enter the tenure type, landlord name, rent, and dates without any extra navigation. For fields already in the rented register, click 'Open' on the row to view their tenure details, then 'Edit Land Tenure' to make changes. You can also reach the tenure form from the Fields tab: open any field card, select the Tenure tab in the drawer, and click 'Edit Land Tenure'." },
      { q: "Can I record a Farm Business Tenancy in BDE Farm Trac?", a: "Yes. The Land Tenure Register supports Farm Business Tenancy (FBT) as one of the tenure types. Record the landlord's name, the annual rent, rent review date, and the FBT start and end dates. The system will flag the record when the rent review date is approaching or the tenancy is nearing expiry. You can record multiple fields under the same tenancy — each field has its own tenure record, so you can reflect different rent rates or review dates per parcel if needed." },
      { q: "How does the blended rent per hectare figure work?", a: "The summary bar on the Land Tenure Register tab calculates a blended average annual rent per hectare across all fields that have a rent or licence fee recorded and are classified as tenanted or licensed. It divides the sum of all annual rent figures by the total area (in hectares) of those parcels. Owned-freehold parcels are excluded from the calculation since they carry no rent. This gives a quick benchmark — useful for comparing against RVO or RICS average rent guidance or checking your rent exposure across the farm." },
      { q: "Can I see yield history for each crop variety on a field?", a: "Yes. Open any field card in the Fields tab and go to the Season History tab in the field drawer. Each crop card on that tab includes a Yield History section showing every harvest recorded for that variety on that field. For each season you can see the yield per hectare (t/ha), total yield in tonnes, moisture at harvest, and quality grade. A summary table at the bottom of the Season History tab lists all crops grown on the field in descending year order with a season-on-season trend arrow — green upward for yield improvement, amber downward for a drop, or a dash where only one season exists for comparison. This lets you track field productivity trends without leaving the Fields page." },
      { q: "How do planting and harvest dates appear in the Week Ahead planner?", a: "When you record a planting date or expected harvest date against a field–crop assignment (set when assigning a crop to a field for the season, or edited afterwards), those dates automatically feed the Week Ahead and Month Ahead planners. A green Planting card appears in the week the drilling is scheduled, prompting you to confirm seed, equipment, and soil readiness and reminding you to log the actual sowing date once drilling is complete. A green Harvest Window card appears in the week the crop is expected to be ready, prompting you to monitor ripeness and plan combining and haulage logistics. Both cards link directly to Fields & Crops." },
      { q: "Can I attach data sheets or seed certificates to a variety in the Crops Register?", a: "Yes. In the Crops Register tab, click on any variety group to expand it. At the bottom of the expanded panel you will find a Variety Documents section. This is where you can attach the AHDB or KWS variety data sheet, the seed drill certificate, or any other relevant variety-level document. Click the dashed upload area to select a PDF, image, or Word document from your computer — it uploads and attaches immediately. Uploaded documents are listed with their filename and an open/download button so you or an inspector can access them without leaving the page. A remove button is available on each document to delete it. Documents are stored against the variety entry and remain accessible regardless of which crop year is selected." },
      { q: "Where do I record the sale price per tonne for a harvested crop?", a: "The Sale Price (£/t) field is on each Harvest Record. Navigate to Field & Crop Management → Harvest Records, open a record to edit it (or fill it in when creating a new one), and enter the agreed or achieved price per tonne. The value is stored in pence for precision and displayed as £ to two decimal places. You can record it at harvest time or come back to fill it in once the trading contract is settled. This figure is picked up automatically by the Season Production Report to calculate revenue and gross margin for the season — no re-entry required." },
      { q: "Where do I record seed cost on a drilling record?", a: "The Seed Cost (£/kg) field appears on the Seed Drilling form in Field & Crop Management → Seed Drilling. Enter the cost per kilogram from your seed invoice. The Season Production Report multiplies this by the seed rate and area drilled to calculate the total seed input cost for the season. On the mobile app the same field appears in the Seed Drilling screen, stored offline and synced automatically." },
      { q: "What is the Season Production Report and how does it calculate gross margin?", a: "The Season Production Report (Field & Crop Management → Season Reports) combines all drilling, fertiliser, spray, and harvest records for a selected crop season into one view. The Financial Summary section at the top calculates five figures automatically: Total Seed Cost (from seed cost per kg on drilling records), Total Fertiliser Cost (from total cost on NVZ application records), Total Spray Cost (from product cost per unit on spray records), Revenue (sale price per tonne × total yield from harvest records), and Gross Margin (Revenue minus total input costs) expressed in both £ and £/ha. The Gross Margin tile turns red when the margin is negative. All figures are computed server-side from your existing records — you do not need to enter any additional data in the report itself." },
      { q: "What is the Black-grass Five-in-Five tracker?", a: "The Black-grass Five-in-Five tracker scores how many of five recognised cultural control pillars — rotational ploughing, delayed drilling, spring cropping, higher seed rate, and fallow or cover cropping — have been used on a field over its last five seasons, following the well-established principle that combining at least five different pillars across five years significantly reduces black-grass seed return. Tick 'Black-grass risk field' on any field's edit form to flag it for tracking; the field's Crop History tab then shows a five-year × five-pillar grid drawn automatically from your existing operations, drilling, cropping, and land use records, plus a warning if the same herbicide MOA/HRAC group has been used on grass-weed applications for three or more consecutive seasons. Season Reports includes a farm-wide summary showing the percentage of flagged fields meeting the five-pillar target and a list of fields still at risk." },
      { q: "What is the Seed Store and how does it track my seed batches?", a: "The Seed Store (Field & Crop Management → Seed Store) is an inventory register for the seed batches you receive from suppliers. For each batch you log the crop, variety, supplier, batch/lot number, TGW (thousand grain weight in grams), bag weight, quantity received, and date received. As you assign that batch to crop assignments in Fields, the recorded quantity is automatically deducted, and a progress bar on the batch card turns amber once stock drops to 15% or below — helping you order more seed before you run out. Batches at zero stock are marked Used Up but stay visible via the 'Show Used-Up Batches' toggle for traceability." },
      { q: "How do I record a Seed Store stocktake?", a: "Open the Seed Store tab within Field & Crop Management on the dashboard and select the Stocktakes sub-tab. Click Record Stocktake. Select the seed batch you are counting — the system quantity auto-fills from the batch's current remaining stock figure. Enter the physical quantity you have counted. A variance badge shows the difference between your physical count and the system figure: green for zero variance, amber for surplus, and red for a shortfall. Enter who conducted the count and confirm the date, then save. The stocktake is written as a permanent audit entry against that batch. The Field Allocation tab on each seed batch lets you see exactly which fields have received seed from that batch across the season — useful for understanding the system stock figure before you begin a count." },
      { q: "How does the Seed Rate Calculator work and why does it factor in soil type?", a: "The Seed Rate Calculator, shown when assigning a crop to a field, converts a target plant population into a recommended seed rate (kg/ha) using the formula seeds/m² = target plants/m² ÷ (establishment % ÷ 100), then seed rate = seeds/m² × TGW ÷ 100. The establishment percentage — which folds germination and field losses into one figure — starts from a base value keyed to the field's recorded soil type (heavier clay soils are given a lower establishment percentage than medium loam) and is adjusted further for the planned drilling date, since late-autumn, winter, and early-spring drilling windows carry a harder establishment risk. For fields flagged in the Black-grass Five-in-Five tracker, the calculator suggests a higher target population of 350 plants/m² instead of the standard 250, reflecting AHDB guidance that a denser crop out-competes black-grass." },
      { q: "Can I print seed bag labels for batches I've drilled?", a: "Yes. From a crop assignment linked to a seed batch, click Print Bag Labels to generate an A4 sheet of Avery-compatible labels (63.5mm × 38.1mm, 21 per sheet in a 3-column × 7-row layout). Each label shows the crop, variety, batch number, supplier, TGW, germination percentage if recorded, the destination field, and planting date, along with your farm name and CPH number — giving full batch-to-field traceability for treated seed bags or seed boxes stored on-farm." },
      { q: "How does the crop reason tag and field map year selector work?", a: "When assigning or reviewing a crop for a field, you can attach one or more reason tags — such as Black-grass suppression, Break crop, OSR interval compliance, Soil structure recovery, or Scheme requirement — explaining why that crop or land use was chosen for the season. These show alongside the assignment in the Crop History view. The Field Map also includes a year selector so you can step back through previous seasons and see exactly what was planted historically in every field — useful for checking OSR break intervals or reviewing rotation diversity for Black-grass Five-in-Five scoring." },
      { q: "How is the crop season determined for a field assignment?", a: "The season (Autumn, Winter, Spring, or Summer) for a crop assignment is derived automatically from the planting date as soon as it is entered. You can still override it manually — for example, if a delayed drilling date still needs to be recorded as an agronomic autumn crop — and once you change it manually it stops auto-updating from the date, so your manual choice is preserved." },
    ],
  },
  {
    title: "Sheep Production",
    icon: Leaf,
    color: "bg-green-50 text-green-700 border-green-100",
    items: [
      { q: "What records does the Sheep Production module cover?", a: "The Sheep Production module provides dedicated records for every stage of the sheep production calendar: tupping (ram-to-ewe service records), pregnancy scanning, weigh-in and DLWG performance tracking, shearing records with BWMB wool merchant traceability, annual vet health plans, and the Red Tractor Sheep Assurance checklist. Sheep flocks are registered and managed centrally in Livestock → Herds & Animals — the single herd and flock register used across the platform — and each Sheep Production record links back to the relevant flock from there. The module sits alongside the core Livestock & Feed Management module where movements, medicine records, lambing records, and welfare assessments are recorded." },
      { q: "How do I record a tupping event?", a: "Navigate to Sheep Production and open the Tupping tab. Click New Tupping Record and select the flock from your herd and flock register (Livestock → Herds & Animals). Record the ram ID and breed (selected from your Sire Register or entered as free text), the breeding group or field the ram was put with, the date put to, the date removed, and the expected scanning date based on the gestation period you set. Multiple tupping rounds per season can be recorded for the same flock. Once saved, the expected scanning date surfaces in the Farm Planner as a reminder." },
      { q: "How does pregnancy scanning integrate with lambing planning?", a: "The Scanning tab records the scanning event with scanner name, scanning date, and the results per ewe or per group — number of singles, twins, triplets, quads, and empty ewes. The scanning summary automatically calculates the overall pregnancy rate and expected litter distribution. The expected lambing date recorded at scanning feeds the Farm Planner as a countdown reminder. Scanning results link back to the tupping record for the same flock so you can track fertility performance across seasons." },
      { q: "How does the Weigh-in and DLWG record work for sheep?", a: "Open Sheep Production and go to the Weigh-in tab. You can record a group weigh-in (average weight per group on a given date) or individual animal weights. The system calculates the daily live weight gain (DLWG) from the previous weigh-in date automatically. A target DLWG can be set per group — the DLWG column is colour-coded green (on or above target), amber (within 10% of target), or red (below target). These records satisfy the performance monitoring requirement in Red Tractor Sheep Assurance and provide the data needed for AHDB benchmarking comparisons." },
      { q: "What shearing details does the system capture and why does BWMB traceability matter?", a: "The Shearing Record captures the shearing date, whether the work was done by farm staff or a contractor (with contractor name and contact details), fleece weight per group in kg, any skirting or dagging notes, and the wool merchant or buyer name and reference. BWMB (British Wool Marketing Board) requires growers to log the quantity and description of wool by flock or clip for certification and payment purposes. Recording the merchant name and clip weight against the shearing date gives you the traceability chain if a quality query arises from your wool merchant." },
      { q: "How does the Red Tractor Sheep Assurance checklist work?", a: "The Red Tractor Sheep Assurance checklist in the Sheep Production module is a structured self-assessment covering the main audit areas: identification and tagging, movement records, medicine records and withdrawal periods, health plans (vet-signed, current), welfare and stockmanship, feed and water provision, and fleece management. Each section has a series of yes/no or compliant/not-compliant items. Tick each item as you review it — the section header shows a colour-coded status (green all complete, amber partial, red none). The checklist can be printed as a formatted pre-inspection document to use during or before an assessor visit." },
      { q: "Does the Sheep Production module flag reportable diseases and prompt APHA notification?", a: "Yes. The Sheep Production disease observation tab includes a Reportable Disease checkbox. When ticked, a red APHA advisory banner appears on the saved record reminding you to contact APHA immediately on 03000 200 301 — mandatory notification of a suspected notifiable disease must be made before laboratory confirmation, not after. A Raise APHA Task button on the advisory pre-fills a task with the disease name, flock, and observation date so the follow-up is tracked in the Task Board. This is designed as a quick-capture field flag for the moment of suspicion — the formal incident record with APHA reference number, isolation measures, and outcome is recorded in Compliance & Plans → Disease & Incident Log." },
    ],
  },
  {
    title: "Goat Production",
    icon: Leaf,
    color: "bg-emerald-50 text-emerald-700 border-emerald-100",
    items: [
      { q: "What records does the Goat Production module cover?", a: "The Goat Production module provides dedicated records for the key stages of the commercial and dairy goat production calendar: mating records (buck details, does exposed, mating method, expected kidding date), pregnancy scanning (barren/singles/doubles/triplets with automatic scanning percentage), weigh-in & DLWG performance tracking with body condition scoring, cull and market records (deadweight, kill-out %, sale value, reason for cull), vaccination programmes, and disease monitoring (CAE, CLA, Johne's, foot rot, cryptosporidiosis, mycoplasma, and FEC). An Analytics tab summarises performance with KPI cards, a kid-type distribution chart, and a DLWG-by-batch chart. Goat herds are registered and managed in Livestock → Herds & Animals — the single herd register used across the platform." },
      { q: "How do I record a goat mating event?", a: "Navigate to Goat Production and open the Mating tab. Click Add Record and select the herd. Record the buck breed (selected from UK commercial and dairy goat breeds — Boer, Anglo-Nubian, Cashmere, Pygmy, Crossbred, and others), the buck's ear tag, the owner if the buck was hired, whether the buck is owned or hired, the number of does exposed, the mating method (natural service, AI with fresh or frozen semen, or embryo transfer), the start and end dates, and the expected kidding date. Tick CIDR / Progesterone Sponge Used if intravaginal devices were used to synchronise oestrus. The mating record prints as a landscape A4 compliance document and is retained for a minimum of 3 years." },
      { q: "How does goat pregnancy scanning work in the system?", a: "Open Goat Production and go to the Scanning tab. Add a scanning record with the scan date, scanner name and company, total does scanned, and the litter breakdown — barren, singles, doubles, and triplets. The scanning percentage is calculated automatically from the litter counts divided by total does scanned. The Analytics tab aggregates all scanning events into a Kid Type Distribution pie chart (barren / singles / doubles / triplets) and shows the average scanning percentage as a KPI card across all recorded rounds." },
      { q: "How does the Goat Weigh-in and DLWG record work?", a: "Open Goat Production and go to the Weigh-in tab. Record a group weigh-in with the date, animal category (Kids, Weanlings, Yearlings, Does, or Bucks), batch or group reference, number weighed, average weight, lightest and heaviest weights, target weight, and body condition score (BCS). DLWG is calculated automatically from the previous weigh-in for the same batch reference. The result is colour-coded green (on or above target), amber (within 10% below), or red (significantly below). A Raise Task button in each record's View dialog lets you create a follow-up task when performance falls below target." },
      { q: "How do I monitor CAE and CLA in the Goat Production module?", a: "Navigate to Goat Production → Health → Disease Monitoring and click Add. Select the monitoring type — CAE (Caprine Arthritis Encephalitis), CLA (Caseous Lymphadenitis), Johne's Disease, Foot rot surveillance, Cryptosporidiosis, Mycoplasma, or Faecal Egg Count — then record the testing body or laboratory, number of samples, positive and negative results, overall status (Pending / Clear / Positive / Inconclusive), actions taken, and the next test due date. Status is shown as a colour-coded badge on each record. CAE monitoring records support CAE Accreditation Scheme documentation requirements; Johne's records track herd risk level across monitoring rounds." },
      { q: "What does the Goat Production Analytics tab show?", a: "The Analytics tab in Goat Production provides a summary across all record types. Four KPI cards show: total mating records, average scanning percentage, average DLWG in g/day, and total cull and market head. Below the cards, a Kid Type Distribution pie chart shows the proportion of barren, singles, doubles, and triples across all scanning events. A DLWG by Batch horizontal bar chart shows the most recent ten weigh-in groups. At the bottom, a Cull & Market Summary shows total records, total head, and total sale value, and a Mating Summary shows total cycles, total does exposed, and the number of buck breeds used." },
    ],
  },
  {
    title: "Venison Production",
    icon: Crosshair,
    color: "bg-green-50 text-green-700 border-green-100",
    items: [
      { q: "What records does the Venison Production module cover?", a: "The Venison Production module covers five key areas for UK deer enterprises: Cull Records (stalking and culling events with species, sex, age class, beat, larder/carcass numbers, liveweight, gralloch weight, carcass weight, kill-out %, cull reason, food safety inspection result, and a notifiable disease suspect flag with mandatory APHA advisory), Carcass Sales (carcass processing and venison sales records with facility type, destination, buyer, Wild Game Declaration number, price/kg, and total value), Herd Monitoring (population survey log with survey method, male/female/young/total counts, M:F ratio, and recruitment rate %), Health Records (vaccination, bTB SICCT and gamma-interferon test results, post mortem, and vet treatment records), and a Firearms & Stalking Certificates Register (Section 1 FC, DSC1, DSC2, WGMI, and other certificates with expiry alerts). Deer herds are registered and managed in Livestock → Herds & Animals." },
      { q: "How do I record a stalking or cull event?", a: "Navigate to Venison Production and open the Cull Records tab. Click Add Cull Record and complete the form: cull date, stalker name, species (Red Deer, Roe Deer, Fallow Deer, Sika, Muntjac, Chinese Water Deer, Reindeer, or Other), sex (Stag/Hind/Buck/Doe/Calf/Fawn), age class (Calf/Fawn, Yearling, Adult), location or beat name, larder number, and carcass number. Enter the liveweight (kg), gralloch weight (kg), and carcass weight (kg) — the system stores all three weights for full carcass yield traceability. Select the food safety inspection result from the dropdown. If a notifiable disease is suspected, tick the Notifiable Disease Suspect checkbox — a red advisory panel will appear reminding you to contact APHA immediately on 03000 200 301 before laboratory confirmation." },
      { q: "What is a Wild Game Declaration and how do I record it?", a: "A Wild Game Declaration (WGD) is required under UK food hygiene regulations (Regulation (EC) No 852/2004, retained in UK law) when deer carcasses are sold into the food chain. It must be completed by a trained hunter (holding a WGMI certificate or equivalent) and accompanies every deer carcass delivered to an Approved Game Handling Establishment (AGHE) or other approved facility. In Venison Production → Carcass Sales, you can record the Wild Game Declaration number against each carcass sale batch along with the facility type, carcass numbers, food safety grade, and buyer details." },
      { q: "How do I record a bTB test result for deer?", a: "Navigate to Venison Production → Health Records and click Add Health Record. Select the event type — either 'bTB skin test (SICCT)' for the Single Intradermal Comparative Cervical Test or 'bTB gamma-interferon blood test'. Enter the test date, number of animals tested, the APHA reference number, and the overall result (Clear / Negative, Standard Reactor, Inconclusive Reactor, or Not Applicable). The result displays as a colour-coded badge: green for Clear, red for Standard or Inconclusive Reactor. Deer are classified as susceptible to bovine TB; farmed deer holdings may be subject to APHA bTB testing requirements in high-risk areas." },
      { q: "How does the Firearms & Stalking Certificates register work?", a: "The Firearms & Stalking Certificates register in Venison Production lets you record every certificate held by your stalkers and team members. Supported certificate types include: Section 1 Firearms Certificate (FC) issued by the local police authority (required for any rifle — renewed every 5 years), Section 2 Shotgun Certificate, Deer Stalking Certificate Level 1 (DSC1) and Level 2 (DSC2) issued by the Deer Initiative/LANTRA, Scottish Stalking Certificate, Hunter Food Hygiene Certificate (WGMI) required for commercial venison supply, and Larder Hygiene certificates. The system tracks the holder name, issuing authority, certificate number, calibre or scope description, issue date, and expiry date. An amber alert banner appears when any certificate expires within 90 days; a red banner appears for expired certificates, reminding you to ensure all stalkers hold current valid authorisation before entering the field." },
      { q: "What population survey methods can I record in the Herd Monitoring tab?", a: "The Herd Monitoring tab supports six population survey methods used by deer managers across the UK: Driven Count (organised drive with counters and recorders), Thermal Imaging — Ground-based (lamping or vehicle-mounted thermal camera), Fixed Point Count / Vantage Point (repeated counts from elevated positions), ADE Count — Aerial (aerial distance estimation from low-level aircraft, used for red deer in Scotland), Thermal Drone Survey (UAV-mounted thermal camera), and Camera Trap Census (remote camera trap grid analysis). For each survey you record the date, species, male/female/young/total counts, male:female ratio, recruitment rate %, observer name, and weather conditions. Regular population surveys are required as evidence for annual deer management plans." },
    ],
  },
  {
    title: "Organic Venison",
    icon: Leaf,
    color: "bg-teal-50 text-teal-700 border-teal-100",
    items: [
      { q: "What does the Organic Venison module cover?", a: "The Organic Venison module provides four compliance tabs for certified organic farmed deer enterprises. Certification: record your certifying body (Soil Association, OF&G, Biodynamic Association, or OF&G Scotland), certificate number, certificate type (Venison/Deer Park, Full Holding, Specific Enterprise Only, or In-Conversion Certificate), issue date, expiry date, scope, and status. Land Register: track each grazing compartment or deer park block through conversion from pre-conversion to certified organic status with area (ha), conversion start date, certified organic date, and certifier reference. Feed & Supplements: log all supplementary feed inputs with organic approval status (Certified Organic, Approved for organic use, Derogation Required, or Not Permitted) and certifier approval reference. Derogations: manage input derogation cases from application through to decision with justification, regulatory basis, approval conditions, and expiry date." },
      { q: "Can wild venison be certified organic?", a: "No. Wild venison cannot hold organic certification status under UK Organic Regulations (retained from EC No. 834/2007). Only farmed deer enterprises — where animals are born and raised under organic management conditions on certified organic land — are eligible for organic certification. The Organic Venison module is designed specifically for farmed deer parks and enclosed deer enterprises seeking Soil Association, OF&G, or equivalent UK certification. Wild deer culled on open ground do not qualify regardless of feeding habits or habitat." },
      { q: "How does the Organic Venison Land Register work?", a: "The Land Register in Organic Venison tracks each grazing compartment or deer park enclosure through the UK organic conversion process. Add each compartment with its name, area in hectares, and current conversion status — one of: Pre-Conversion (not yet notified to certifier), Year 1 In-Conversion, Year 2 In-Conversion, Certified Organic, Suspended, or Withdrawn. Record the conversion start date and, once achieved, the certified organic date. Link each parcel to a certifying body and record the certifier's parcel reference so records cross-reference your inspection documents. Previous land use (e.g. conventional arable, improved pasture) should be recorded as it is reviewed by inspectors when evaluating conversion eligibility." },
      { q: "How do I record a derogation for organic venison?", a: "Navigate to Organic Venison → Derogations and click New Derogation. Enter a case reference number for your own tracking (e.g. DERG-2025-001), the input name, input type, and regulatory basis (e.g. UK Organic Reg Art. 24). Select your certifying body and enter the application date. Under UK Organic Regulations a derogation must be applied for before the input is used — record the justification explaining why no certified organic alternative is available. When a decision is received, update the status to Approved or Refused and enter the decision date. For approved cases, record the expiry date and any conditions attached to the approval. The derogations register is reviewed at annual organic inspections." },
    ],
  },
  {
    title: "Beef & Cattle Production",
    icon: PawPrint,
    color: "bg-orange-50 text-orange-700 border-orange-100",
    items: [
      { q: "What records does the Beef Production module add beyond the core Livestock module?", a: "The Beef Production module adds records specifically needed for commercial beef enterprises that the core Livestock & Feed Management module does not cover: weigh-in and DLWG performance tracking per group, beef finishing records (entry/exit weights, shed/group assignment, feed regime, and target finish weight), body condition scoring at production-stage milestones, and deadweight settlement recording (kill date, EUROP grade, fat class, kill-out %, and net settlement value linked to cattle movement records). Core medicine records, movements, vet visits, and lambing/calving records remain in the Livestock & Feed Management module." },
      { q: "How does the Beef Weigh-in and DLWG tracking work?", a: "Open Beef Production and go to the Weigh-in tab. Record a weigh-in event with the date, group or shed name, number of animals weighed, and either an average group weight or individual animal weights. The system calculates DLWG automatically from the previous weigh-in for the same group. A breed target DLWG can be set per group — the result column is colour-coded green (on target), amber (within 10% below), or red (significantly below target). Individual animal weights can be linked to ear tags from the Individual Animal Register for full per-animal traceability." },
      { q: "How do I set up and close out a Beef Finishing Record?", a: "From the Beef Production module, go to the Finishing tab and click New Finishing Record. Enter the group name, shed or pen assignment, entry date, number of animals, entry weight, target finish weight, target finish date, and the starting feed regime. The record remains open as the group progresses through finishing. When the group is sold or sent to slaughter, open the record and click Close Out — enter the exit date, exit weight, actual DLWG achieved, final EUROP conformation grade and fat class assessed on farm, and the abattoir reference. A linked Deadweight Settlement can then be added with the kill data from the settlement sheet." },
      { q: "What does the Deadweight Settlement record capture and how does it link to cattle movements?", a: "The Deadweight Settlement record logs the abattoir kill data: kill date, slaughter or kill number, number of animals, cold deadweight (kg), kill-out percentage, EUROP conformation grade, fat class, value per kg DW (in pence), and net settlement value. An optional Contract Reference field links the settlement to a forward contract. The record can be linked to the cattle movement record for that consignment — when linked, the movement record shows a Settlement Recorded badge and the settlement record shows the AML movement reference, creating a complete audit trail from farm dispatch to kill sheet." },
      { q: "Can I record Beef Body Condition Scores at key production stages?", a: "Yes. The BCS tab in Beef Production lets you record group or individual BCS assessments on the 1–5 scale. You select the production stage from a fixed list — Housing, Pre-Service, Scanning, Mid-Pregnancy, Pre-Calving, Weaning, Turnout, or Ad Hoc — so the context of each assessment is always clear. The target BCS range for each stage is shown alongside the recorded score. Animals or groups scoring below the target minimum for the production stage are flagged with an amber action card. All BCS records are included in the print-ready Beef Production report for Red Tractor audit evidence." },
    ],
  },
  {
    title: "New Platform Features",
    icon: LineChart,
    color: "bg-blue-50 text-blue-700 border-blue-100",
    items: [
      { q: "What is the Carbon Auto-Calculator and how does it work?", a: "The Carbon Auto-Calculator is a tab within the Environment & Sustainability module. It automatically aggregates your recorded data — fuel consumption, fertiliser applications, livestock numbers, feed deliveries, and purchased electricity — and applies the DEFRA 2023 Greenhouse Gas Conversion Factors to calculate your Scope 1 (direct farm emissions), Scope 2 (purchased energy), and Scope 3 (supply chain) emissions. You do not enter any figures manually into the calculator — it reads from your existing records across other modules. The results are displayed as a summary table by emissions category with a total farm footprint in tCO₂e per year and a per-hectare intensity figure. A printable carbon summary report is available for scheme submissions or advisor review." },
      { q: "What is the Crop Rotation Planner and how do I use it?", a: "The Crop Rotation Planner is a tab within Field & Crop Management. It shows a grid with your fields as rows and crop years as columns, displaying the crop grown in each field in each year from your existing records. A colour-coded cell system makes it easy to spot rotation gaps and sequence issues. An OSR break interval check automatically flags any field where oilseed rape has been grown in two out of the last three years — the cell turns amber with a warning, since a minimum two-year break is required to manage clubroot and light leaf spot. Unrecorded field-years show as an empty grey cell. You can also set a planned crop for future years within the planner, and those planned entries are shown in a lighter shade to distinguish them from confirmed records." },
      { q: "How does the Training Competency Matrix work?", a: "The Training Competency Matrix is a tab within Staff & Training. It shows a grid with your staff members as rows and certificate types as columns. Each cell in the grid shows the expiry date (or 'Not held') for that staff member's certificate of that type, colour-coded green (valid), amber (expiring within 90 days), or red (expired or not held). A filter at the top of the page lets you show only spray operator certificates (PA1, PA2, PA6) — useful for confirming all operators are compliant before a spray programme begins. The matrix also drives the spray operator certification warning that appears in the Sprays & Inputs module when you select an operator whose PA certificate is not valid." },
      { q: "What is the Benchmarking Panel and how are the benchmarks calculated?", a: "The Benchmarking Panel is a tab within Finance & Business. It displays your farm's key performance indicators alongside industry benchmarks drawn from AHDB (Agriculture and Horticulture Development Board) and Andersons Farm Business Survey data. Metrics include gross margin per hectare (combinable crops), cost of production per tonne, overhead cost per hectare, output per litre (dairy), suckler cow gross margin, and finishing gross margin (beef), among others. Your farm's figure is calculated automatically from your recorded costs, yields, and sales. The benchmark shows the top-third (green), average (amber), and bottom-third (red) performance bands so you can see where your farm sits. Benchmarks are updated annually when AHDB and Andersons publish new figures." },
      { q: "What does the NVZ Budget Calculator do?", a: "The NVZ Budget Calculator is a tab within the Soil Management / NVZ module. It calculates the available nitrogen budget for each field by taking the DEFRA field-level nitrogen limit (drawn from your NVZ designation and soil type on file), subtracting the nitrogen applied to date from your logged NVZ fertiliser application records, and showing the remaining budget in kg N/ha. Fields approaching or exceeding their limit are highlighted in amber or red. The calculator also checks whether your applications fall within or outside the NVZ closed period dates and warns if any applications have been logged during a restricted period. This gives a field-by-field compliance view without needing to run a separate spreadsheet." },
      { q: "What is the correct order to set up Labour Management?", a: "Labour Management has five tabs that build on each other and should be set up in order. Step 1 — Rota & Shifts: add your active staff members first (they must be in your Farm Members list), then plan the weekly rota by assigning each person a shift for each working day. The rota is your planned schedule and is the foundation the Submission Status grid uses to know who should be submitting timesheets. Step 2 — Timesheets: once staff are in the rota, they submit hours daily from the mobile app (or you enter them manually on the dashboard). Each entry captures date, task type, regular hours, overtime, and Approved By. The Submission Status grid at the top of the Timesheets tab shows a live traffic-light view — green (✓ approved), amber (~ submitted but awaiting approval), red (! missing), grey (– off). Step 3 — Holiday & Absence: record all leave so the rota and WTR calculations stay accurate. Step 4 — Pay Summary: once hourly rates are set per staff member, monthly pay is calculated automatically from timesheet hours. Step 5 — Working Time: the 17-week rolling average is calculated automatically from timesheet entries and flags any WTR breaches." },
      { q: "How does the timesheet submission and approval workflow operate?", a: "Staff submit timesheets from the mobile app at the end of each working day. They add one or more task entries (task type and hours), then tap Submit — each entry is sent to the server immediately and appears as amber (~) in the Submission Status grid on the dashboard. The farm manager (or approving supervisor) sees a notification badge on the Timesheets tab showing how many submissions are awaiting approval, and receives an SMS alert if SMS notifications are enabled on their account. To approve, the manager opens the relevant entry in the Timesheets table, edits it, and types their name in the Approved By field — the entry then turns green (✓) in the Submission Status grid. Entries can also be added manually on the dashboard by clicking Add Entry, in which case the Approved By field can be filled in at the same time. Note: currently Approved By is a free-text field, meaning any approver's name can be entered — department managers can approve entries for their own teams by entering their name directly." },
      { q: "How does the Rota & Shifts planner work?", a: "The Rota & Shifts tab is the first tab you should set up in Labour Management. It shows a weekly grid with one column per day (Mon–Sun) and one row per active staff member. For each person, you assign a shift type for each working day: Full Day, AM Only, PM Only, Night Shift, or one of the absence types (Day Off, Holiday, Sick). You can navigate forward and back through weeks using the arrow buttons. The rota feeds the Submission Status panel — if a staff member is not rostered on a given day they show as blank (not rostered), and if rostered but with no timesheet submitted they show as red (!) once that day has passed. Print the weekly rota using the Print button for pinning on notice boards or sharing with staff without app access." },
      { q: "How does the Holiday & Absence tracking work?", a: "The Holiday & Absence tab records all leave and absence for every staff member. Each entry captures the absence type (Annual Leave, Sick Leave, Compassionate Leave, Maternity, Paternity, Unpaid Leave, Public Holiday, Training Day, or Other), start date, end date, total days, approval status, and optional notes. Annual leave entitlement for each staff member is managed via the Edit entitlement link on their row — set the annual entitlement in days and any days carried over from the previous year. The system automatically calculates remaining entitlement by deducting recorded Annual Leave days from the total, so the current balance is always visible. Days absent are also reflected in the rota so the Submission Status grid shows those days as grey (–) rather than red (!). Staff can also submit leave requests directly from the mobile app — they select a leave type (Annual Leave, Compassionate Leave, Unpaid Leave, Training Day, or Other), enter start and end dates, and optionally add a note before submitting. The request arrives on the dashboard as Pending and triggers an SMS notification to all opted-in managers on the account. The Holiday & Absence tab displays a badge showing how many requests are awaiting approval, and an amber Pending Leave Requests panel appears at the top of the tab listing each request with the staff member's name, leave type, date range, days count, and any notes. Managers can approve a request with a single click or open a Decline dialog where they can optionally add a reason — the reason is stored with the record and included in the SMS sent back to the staff member confirming the outcome." },
      { q: "What is the Working Time Regulations compliance tab and who does it apply to?", a: "The Working Time Regulations 1998 set a maximum 48-hour average working week, calculated over a rolling 17-week reference period. The Working Time tab in Labour Management automatically calculates the 17-week rolling average weekly hours for every staff member from their timesheet entries — no manual input is needed. Any worker whose average exceeds 48 hours is flagged amber (warning, approaching limit) or red (breach). The tab also records each worker's opt-out status — workers who have signed a valid written opt-out are exempt from the 48-hour cap but must still be monitored and can be toggled in the system. This tab provides the documented, systematic monitoring that HMRC and the Health & Safety Executive require. The WTR applies to almost all workers including casual and zero-hours staff; only the self-employed are excluded." },
      { q: "How does the Pay Summary work and how do I export payroll data?", a: "The Pay Summary tab shows a monthly breakdown for each staff member: regular hours worked (from timesheet entries), overtime hours, the applicable hourly rate for that period, and calculated gross pay. Hourly rates are managed per staff member with an effective-from date, so if a rate changes mid-year, historic pay calculations use the old rate and future months use the new one automatically — no back-editing required. Annual leave entitlement and carried-over days are also visible here. A CSV Export button downloads the monthly summary as a spreadsheet suitable for uploading to payroll software or sharing with a payroll bureau. Note that Pay Summary shows gross pay only — it does not calculate tax, NI, or pension deductions, which should be handled by your payroll software or bureau." },
      { q: "What is the Holiday Planner and how does it help with scheduling?", a: "The Holiday Planner is a calendar view of the Holiday & Absence tab. Toggle between List and Planner using the switch at the top of the tab. In Planner mode, the current month is displayed as a grid with staff members as rows and calendar days as columns. Each approved absence appears as a colour-coded cell: green for Annual Leave, red for Sickness, purple for Compassionate Leave, pink for Maternity or Paternity, sky blue for Training Day, and teal for TOIL. Pending (unapproved) requests appear in amber so you can see what is waiting for a decision. Any Holiday shifts from the Rota & Shifts planner that do not have a matching absence record are shown in lime green with a 'Rota only (unlogged)' label — this lets you spot days where someone has been given holiday on the rota but the formal absence record has not yet been entered. At the bottom of the grid, a 'Staff off' count row shows how many staff are absent each day; any day where 40% or more of the team are absent is highlighted in red, flagging a potential scheduling conflict before you approve further requests. Use the left and right arrows to navigate between months to plan ahead. Clicking any cell opens the full absence record for that person and day." },
      { q: "How do I print a blank leave request form for staff without the mobile app?", a: "On the Holiday & Absence tab, click the 'Blank Leave Form' button in the top-right toolbar. This generates and opens a print-ready A4 form (reference FT-LR-01) that you can print immediately or save as a PDF. The form includes: tick-box leave type selection (Annual Leave, Sick Leave, Compassionate Leave, Maternity / Paternity Leave, Training Day, TOIL, Unpaid Leave, or Other with a free-text box), a date range section (start date, end date, and total days), an employee declaration with a signature block and date, and a manager decision section with options for Approved, Declined, or Part-approved with a comments box. The farm name pre-fills automatically from your Farm Settings. Printed forms should be signed by the employee and countersigned by the manager. Once approved or declined, transcribe the outcome into the Holiday & Absence tab by adding a new absence record or updating the existing one — this keeps the digital record complete for compliance purposes." },
      { q: "What is the Red Tractor Audit Pack Generator?", a: "The Red Tractor Audit Pack Generator is available in the Compliance module. It collects records across all active modules for a selectable date range and assembles them into a print-ready audit pack structured around the Red Tractor Combinable Crops, Beef & Lamb, or Dairy standards (select which scheme applies). The pack includes sections for: spray application records with operator certificate status, soil sampling and NVZ records, livestock medicine records with withdrawal periods, movement records, staff training certificates, risk assessments and COSHH, biosecurity plan summary, and equipment calibration and maintenance records. Each section has a summary compliance status. You can print the full pack in one operation for an assessor visit or generate a PDF for sharing with an advisor." },
      { q: "What is Multi-Farm Consolidated Reporting?", a: "If your account has more than one farm holding registered, the Group Overview tab on the main dashboard shows a consolidated compliance status across all your holdings. Each holding is shown as a card with its overall Red Tractor compliance status, a count of overdue tasks, any outstanding certificate expiries, and a traffic-light indicator for the key compliance areas (medicines, movements, inspections, training). You can click through to any individual farm's full dashboard from the group view. This is designed for farm groups, estates, and farming companies managing multiple CPH numbers under one account without needing to log in separately for each." },
      { q: "Do date fields prevent me from entering future dates on historical records?", a: "Yes. Every date field in BDE Farm Trac is bound to a logical date range. Fields that record something that has already happened — medicine treatments, service events, fuel drawdowns, spray applications, welfare assessments, harvest dates, and similar past-event records — will not accept a date in the future. Fields that schedule a future action — such as expected calving dates and planned spray windows — will not accept a date in the past. These restrictions apply on both the mobile app and the dashboard. They prevent the most common cause of compliance record errors: a date entered in the wrong year or month by mistake. If a date field will not accept the date you are entering, check whether the record type requires the date to be in the past or the future — the field type determines the constraint." },
      { q: "Do operator, assessor, and 'recorded by' fields fill in automatically when I start a new record?", a: "Yes. When you open a new record form — on either the mobile app or the dashboard — fields that ask for the name of the operator, assessor, recorded-by person, or completing staff member are pre-filled with your logged-in user's name automatically. You can change the name if you are entering a record on behalf of a colleague, but in most cases — where you are the person doing the work — you do not need to type your name at all. This applies across the platform to fields such as Operator on fuel drawdown records, Assessed By on body condition and mobility scoring forms, Recorded By on grain drying and conditioning entries, and Completed By on inspection records, on both the mobile app and the dashboard." },
      { q: "What is the Fetch Live button in the Add Weather Reading dialog?", a: "The Fetch Live button in the Add Weather Reading dialog uses your browser's location to call the Open-Meteo API and retrieve current weather conditions at your farm's coordinates. Temperature (°C), wind speed (km/h), relative humidity (%), and precipitation are returned and auto-fill the matching fields in the form instantly. No API key or separate weather service subscription is needed — Open-Meteo is a free, open-data weather service. You can edit any auto-filled field before saving. Fetch Live is the fastest way to log an accurate weather snapshot at the exact moment of a spray application." },
      { q: "What is the Vehicle Weather Device Register?", a: "The Device Register tab (fourth tab on the Weather Records page) is a named list of the vehicle-mounted and portable weather instruments used on your farm. For each device you record the device name, manufacturer, model, serial number, installation type (portable / permanent vehicle-fixed / fixed field sensor), last calibration date, and the next calibration due date. Once a device is registered it appears as an option in the device picker when you add a vehicle weather reading — selecting it automatically populates the serial number on the reading record, creating a clear chain of custody from the physical instrument to the logged measurement. This is useful for Red Tractor and other audit schemes that require traceability of recording equipment." },
      { q: "How does calibration tracking work for vehicle weather devices?", a: "Each device in the Device Register has a Last Calibration Date and a Calibration Due Date. BDE Farm Trac colour-codes the calibration status of every device in the register: green OK for devices whose calibration is not due within 30 days, amber Due soon for devices within 30 days of their due date, and red Overdue for devices that have passed their calibration due date. If any device is within 30 days of its due date or already overdue, a prominent amber alert banner is displayed at the top of the Device Register tab listing the affected devices, their serial numbers, and the exact due date. This ensures calibration lapses are noticed before they affect spray application evidence records." },
      { q: "Can I link a vehicle weather reading to a specific calibrated device?", a: "Yes. When you add a vehicle weather reading on the Vehicle Stations tab, the form shows a Device Register picker alongside the vehicle picker. The device picker lists all active devices from the Device Register tab and shows the device name and serial number. Selecting a device automatically associates that reading with the specific instrument, including its serial number. If no devices are registered yet the form shows a prompt to add devices via the Device Register tab. You can also leave the device field unlinked if the reading was taken without a registered instrument." },
      { q: "Can I print the device register for an audit pack?", a: "Yes. A Print Register button appears in the top-right corner of the Device Register tab when at least one device is registered. Clicking it triggers the browser's standard print dialog. The printed output shows all device names, manufacturers, models, serial numbers, installation types, calibration dates, and calibration due dates — suitable for inclusion in an audit pack or calibration management folder." },
      { q: "Do staff receive a notification on their phone when a task is assigned to them?", a: "Yes. When a task is assigned on the dashboard, the staff member receives both an SMS text message and an instant push notification on their mobile app. The push notification appears on the device's lock screen and notification tray — tapping it opens My Task Inbox in the BDE Farm Trac mobile app directly. Push notifications are registered automatically the first time a staff member logs in to the mobile app, and are delivered alongside the SMS so workers are alerted even if the app is not currently open." },
      { q: "What are BVD Testing and Johne's Disease monitoring records and where do I find them?", a: "Both are now part of the Livestock module. The BVD Testing Register (Livestock → BVD Testing) records every Bovine Viral Diarrhoea surveillance test against a herd — test type (blood ELISA, ear notch tissue tag, bulk milk ELISA, or colostrum antibody), laboratory, number of animals, result (Negative / Low Positive / Positive), action taken, and lab certificate reference. The herd card in Herds & Flocks shows the most recent BVD status badge at a glance. The Johne's Disease Monitoring Register (Livestock → Johne's Disease) records each quarterly or annual monitoring round — test method (blood ELISA, milk ELISA, or faecal PCR), laboratory, result category (Negative / Low Risk / Low Positive / High Positive), herd risk level (Low / Medium / High per CHECS / AHDB guidance), and actions applied. Both registers are required by Red Tractor Beef & Lamb and Dairy standards, and records must be retained for a minimum of three years." },
      { q: "How do I record a casualty or emergency slaughter event and is it available on mobile?", a: "Yes — Casualty / Emergency Slaughter records can be created from the dashboard (Livestock → Casualty Slaughter) or from the Record tab in the mobile app. The record captures the species and ear tag of the animal (RFID-scannable on mobile), the reason requiring on-farm slaughter, the method used (captive bolt, free bullet, or barbiturate injection by a vet), the name and WASK/WATOK certificate reference of the person performing the slaughter, any witness present, vet involvement, and carcase disposal details (disposal method, collection date, and waste transfer note or NFAS reference). A photo can be attached for the WASK certificate or disposal contractor documentation. GPS coordinates are captured automatically on mobile. The mobile record is designed for immediate in-the-field use — it saves offline and syncs to the dashboard when connectivity is restored. Red Tractor requires a written record of every on-farm emergency killing, retained for a minimum of three years. The person performing the slaughter must hold a current WASK certificate (cattle and sheep) or WATOK certificate (pigs)." },
      { q: "What are Campylobacter Monitoring and Pig Salmonella Monitoring records?", a: "These are two new Red Tractor compliance record types for poultry and pig producers respectively. Campylobacter Monitoring (Poultry Production → Campylobacter Monitoring) records every flock's Campylobacter National Control Programme (NCP) test result — flock, slaughter date, slaughter house, test type (neck skin pooled swab, boot swab, or caecal content), FSA submission reference, result (Negative / Low Positive / Positive), and any biosecurity interventions applied following a positive finding. Red Tractor Poultry requires NCP records for all broiler flocks entering the food chain. Pig Salmonella Monitoring (Pig Production → Salmonella Monitoring) records each quarterly NSMP blood serology sampling round — pig group, number of samples, APHA or approved laboratory, result category (Category 1 low / Category 2 moderate / Category 3 high), seroprevalence percentage, and actions applied. Category 3 results trigger a compliance alert in the dashboard and Week Ahead Planner and require a documented corrective action plan. Red Tractor Pigs standards mandate quarterly NSMP participation." },
      { q: "Can I filter livestock production records by year?", a: "Yes. All recording tabs across the specialist livestock production modules include a year filter — this applies to Sheep Production (tupping, scanning, weigh-in, shearing, disease monitoring), Goat Production (mating, scanning, weigh-in, cull, vaccination, disease monitoring), Beef Production (weigh-in, finishing, body condition scoring, deadweight settlement), Venison Production (cull records, carcass sales, herd surveys, health records), Pig Production (stockmanship checks, tail biting records, feed records, movements, kill records, Salmonella monitoring), Poultry Production (chick purchases, thinning records, Campylobacter monitoring), Dairy (body condition scoring, mobility scoring, bulk tank, Johne's Disease monitoring), Organic Livestock (Outdoor Access Log), and Organic Dairy (Feed & Nutrition). The filter defaults to the current year on every tab so your most recent records are always shown first. Select a previous year to review historical compliance data or generate records from a past season for a Red Tractor audit pack." },
      { q: "Can I attach documents to individual records in the livestock production modules?", a: "Yes. Every record row in every recording tab across Sheep Production, Goat Production, Beef Production, Venison Production, Pig Production, Poultry Production, Dairy, Organic Livestock (Outdoor Access Log), and Organic Dairy (Milk Collections, Herd Conversion, and Feed & Nutrition) has a compact document attachment button. Clicking it opens an attach or view dialog where you can upload a PDF, photo, or Word document from your computer and link it permanently to that specific record — for example a vet certificate on a health record, a settlement sheet on a deadweight record, a scan certificate on a pregnancy scanning record, or a lab report on a Campylobacter monitoring result. On selected record types — including Pig Stockmanship Checks, Pig Tail Biting Assessments, Dairy Johne's Disease monitoring records, Poultry Chick Purchase records, Poultry Campylobacter Monitoring records, and Organic Dairy Milk Collection records (cattle, sheep dairy, and goat dairy) — the full view dialog also includes a RecordAttachments panel showing all documents linked to that record alongside the structured data, giving a complete evidence file for each individual compliance record." },
      { q: "What is the IPM Plan and how does it link to spray application records?", a: "The IPM Plan (Sprays & Inputs → IPM Plan) is a written farm-level strategy required by Red Tractor Combinable Crops and Horticulture standards. It is structured into five sections: pest and disease threshold monitoring approach, action thresholds used (AHDB or farm-specific), non-chemical control measures in use (rotation, resistant varieties, biological controls, habitat management), spray intervention rationale, and plan review schedule. A Plan Version, Author, Last Review Date, and Next Review Due date are tracked automatically. The plan is printable as a formatted A4 compliance document. Individual spray application records link back to the IPM Plan via a Spray Rationale field — so the monitoring trigger or threshold evidence that justified each specific application is recorded against the spray record, providing a complete audit trail from written plan to field application." },
      { q: "What is a LERAP assessment and when do I need to record one?", a: "A LERAP (Local Environmental Risk Assessment for Pesticides) must be carried out before applying a Category A or Category B product within the buffer zone distance of a watercourse, ditch, or drain. Category A products always require the full label buffer — a LERAP confirms compliance. Category B products allow a LERAP to evaluate whether the buffer may be reduced based on site conditions, field characteristics, and equipment in use. LERAP Assessments are recorded in Sprays & Inputs → LERAP Assessments on the dashboard, or directly from the Record tab in the mobile app. Each assessment is automatically assigned a unique LERAP-{id} document reference (e.g. LERAP-42) when saved. The form captures: assessment date, CRD Assessment Step (Step 1 — notify only, Step 2 — full buffer maintained, Step 3 — full assessment performed), field, product (standard buffer auto-fills from the product record), watercourse description and type, standard and LERAP buffer distances, crop type and soil type (both auto-fill from the field record where recorded), outcome (buffer maintained, reduced buffer, no spray, or pending review), reduction justification, valid-until date, and assessor name. The assessor must be selected from your Staff register — assessors must hold PA1 plus the relevant extension certificate (PA2, PA6 etc.). If the outcome is set to Pending Review, you can assign a named farm member who will receive an automatic email notification with the LERAP reference. Records must be retained for a minimum of three years." },
    ],
  },
  {
    title: "Viticulture",
    icon: Grape,
    color: "bg-purple-50 text-purple-700 border-purple-100",
    items: [
      { q: "What records does the Viticulture module cover?", a: "The Viticulture module provides twelve tabs covering the full range of UK vineyard and winery compliance. Vineyard records: Vine Register (variety, rootstock, planting details), Vineyard Blocks with full planting lifecycle (each block is a permanent geographic site; individual plantings track Active, Suspended, or Removed status; retire a planting with a deactivation record capturing reason type — temporary suspension, grubbed up, replanting, or other — plus operator and notes; replant a block to create a new planting generation linked to the site's complete history), Phenology Records (BBCH growth stage observation log), Canopy & Pruning Operations (all vineyard operations from winter pruning through to green harvest), Harvest Records (yield, must chemistry — Brix, pH, titratable acidity, potential alcohol — and botrytis status), and Disease & Pest Scouting (pressure ratings for all major UK vine pests, automatic notifications on critical findings, and mandatory notifiable organism flags for Xylella fastidiosa and Phytophthora viticola). Winery compliance tabs: Licensing (premises and personal licence records), Excise & Duty (HMRC wine duty return register), Tastings & Tours (cellar door and tasting event log), Age Verification (Challenge 25 ID check records), and Wine Production (SO₂ compliance and additive records per vintage). Every tab has CSV export, view-before-edit record dialogs, and per-record task assignment. The four dedicated mobile screens (scouting, phenology, operations, harvest) each include an active block picker that pulls your registered blocks, shows active blocks in green and suspended blocks in amber, and falls back gracefully to manual text entry when offline." },
      { q: "What other modules are included automatically with a Viticulture or Organic Viticulture subscription?", a: "Both the Viticulture and Organic Viticulture subscriptions include bundled access to five additional modules at no extra charge: Sprays & Inputs (spray application records and product management), Health, Safety & Risk (COSHH assessments for pesticide products), Staff & Training (PA1/PA6W operator certificate records), Equipment & Vehicle Management (NSTS sprayer testing and equipment register), and Trade Contacts & Stock (agrochemical supplier and stock item management). These modules are bundled because they are legal compliance requirements of commercial vineyard operations — COSHH assessments are required for every pesticide product under the Control of Substances Hazardous to Health Regulations, PA1/PA6W certificates are required for all spray operators, and NSTS sprayer testing is required every 3 years. Bundled module access appears automatically in your navigation and dashboard without any additional subscription steps." },
      { q: "How do I set up the Vine Register and what varieties and rootstocks are available?", a: "Navigate to Viticulture and open the Vine Register tab. Click Add Vine to open the entry form. The Variety field is a dropdown containing 24 UK-grown varieties including Bacchus, Pinot Noir, Pinot Gris, Pinot Blanc, Pinot Meunier, Chardonnay, Rondo, Solaris, Regent, Sauvignon Blanc, Müller-Thurgau, Ortega, Seyval Blanc, Reichensteiner, Madeleine Angevine, Dornfelder, Phoenix, Siegerrebe, Gewürztraminer, Kernling, Maréchal Foch, Johanniter, Cabernet Cortis, and Other. The Rootstock field offers 14 options: SO4, 5C Teleki (5C), 420A, 3309 Couderc (3309C), 161-49 Couderc, 101-14 Millardet de Grasset, Riparia Gloire de Montpellier, 1103 Paulsen, 110 Richter, 140 Ruggeri (140Ru), 196-17 Castel, Börner, Gravesac (Fercal × 161-49), 41B, and Own Rooted. Other fields capture vine count, plant spacing (m), date planted, GI Classification (English Wine PDO, English Wine PGI, Welsh Wine PDO, Welsh Wine PGI, UK Table Wine, or No GI — used for geographical indication compliance under UK wine regulations), and wine colour (White, Rosé, Red, Sparkling base, or Multiple). You can also flag a vine as removed from the register, recording the removal date and reason for a permanent audit trail." },
      { q: "How do BBCH phenology records work and which stages are covered?", a: "Open Viticulture and go to the Phenology tab. Each record captures the observation date, vineyard block, BBCH growth stage, percentage of vines that have reached that stage, a free-text description, observer name (pre-filled from your logged-in user), and air temperature at time of observation. All 23 standard BBCH stages are available in the dropdown, from Stage 00 (Winter dormancy — buds dormant) through to Stage 97 (Harvest ripeness). The full sequence covers budbreak stages (01–09), shoot development (10–19), leaf development (11–18), inflorescence emergence (53–57), flowering (60–69), berry development (71–79), veraison and ripening (81–89), and harvest (91–97). You can log multiple observations per stage to track the progression across a block over the season. All records export to CSV for season-by-season comparison or winery reporting." },
      { q: "How do I record a disease or pest scouting walkabout?", a: "Open Viticulture and go to the Disease Scouting tab. Each scouting record captures the scout date, vineyard block, observer name (pre-filled), and pressure ratings on a four-point scale (0 None, 1 Low, 2 Medium, 3 High) for six pathogens and pests: Botrytis, Downy Mildew, Powdery Mildew, Phomopsis, Leafhopper, and Spider Mite — plus a Vine Weevil sighted flag and an Eutypa Dieback sighted flag. Two additional flags cover notifiable organisms — Xylella fastidiosa suspected and Phytophthora viticola suspected — which trigger a mandatory red alert reminding you to contact APHA immediately on 0300 1000 313 before moving any plant material. You can record action taken and the next planned scout date. When you save a scouting record, the system automatically evaluates the findings and raises in-app notifications: critical (with SMS if the SMS Alerts module is active) for Xylella fastidiosa, Phytophthora viticola, Vine Weevil sightings, and any disease at High pressure; warning for Medium disease pressure, Eutypa dieback, and elevated Leafhopper or Spider Mite levels. On the web dashboard, the Raise Task dialog opens automatically after saving a concerning record so you can assign a spray-review or investigation task to the right member of staff straight away. The mobile app shows the same task-raise prompt for high-pressure records." },
      { q: "What does the harvest record capture and can I export it for the winery?", a: "Open Viticulture and go to the Harvest tab. Each harvest record captures the harvest date, vineyard block, total yield in kg, yield per vine (kg/vine), yield per hectare (t/ha), and must chemistry: Brix degrees, pH, titratable acidity (g/L), and potential alcohol percentage. A Botrytis Present checkbox reveals a Botrytis Percentage field if ticked — when botrytis is recorded, an amber advisory is shown on the saved record reminding you to review the crop with your winemaker before processing. The Harvest Destination field is a three-option selector: Own Holding / Own Processing (grapes processed on the same holding), Contract Processor / Contract Winery (grapes sent to a third-party winery under contract), or Grape Sale (grapes sold without further processing). Selecting Contract Processor or Grape Sale reveals a Trade Contact picker populated from your Trade Contacts & Stock register so you can link the harvest record directly to the processor or buyer. The operator name is pre-filled from your logged-in user. If grape condition is rated as Poor or botrytis exceeds 30%, a Raise Task prompt opens automatically after saving so you can assign a winemaker review task without leaving the flow. All harvest records are exportable to CSV from the Export CSV button on the Harvest tab — the file includes all chemistry data in a format suitable for winery intake documentation. View-before-edit record dialogs show the full detail of any record before opening the edit form." },
      { q: "What canopy and pruning operations can I record?", a: "Open Viticulture and go to the Operations tab. The Operation Type dropdown covers 12 types grouped by season and purpose: Winter Pruning, Spur Pruning, Guyot Pruning, Cane Renewal (all winter), Shoot Thinning, Shoot Positioning / Tucking In, Leaf Removal, Sucker Removal (spring/summer canopy), Green Harvest / Bunch Thinning, Shoot Trimming / Topping (summer), and Mechanical Harvest and Hand Harvest (harvest operations). Each record captures the date, block, pruning system (Guyot, Cordon, Gobelet / Bush Vine, or other free text for Cane Pruned, Spur Pruned, VSP, Scott Henry, and more), target buds per vine, actual buds per vine, pruning weight (kg/vine) to three decimal places, shoots removed percentage, leaves removed zone (Lower, Middle, Upper, or Full Canopy), machine used, operator name (auto-filled), contractor name, and hours worked. Export all operations to CSV for labour and agronomist reporting." },
      { q: "What are the four Viticulture mobile screens?", a: "The BDE Farm Trac mobile app includes four dedicated viticulture recording screens. Vine Scouting — a walkabout disease log with tap-to-set pressure pickers (None / Low / Medium / High) for each disease and pest, notifiable organism checkboxes (Xylella fastidiosa and Phytophthora viticola) that trigger an APHA mandatory alert, and a Raise Task flow for high-pressure findings. Vine Phenology — a BBCH growth stage picker with season filter tabs (Winter / Spring / Summer / Autumn) to narrow the stage list, with percentage reached and temperature fields. Vine Operation — an operation type picker grouped by season and purpose, with a pruning sub-form (system, target and actual bud counts, pruning weight per vine) that appears automatically for pruning operation types, plus staff picker and contractor field. Vine Harvest — a vintage record screen with total yield, per-vine yield, per-hectare yield, must chemistry (Brix, pH, TA, potential alcohol), grape condition chips, botrytis flag with percentage and amber advisory, harvest destination type selector (Own Holding / Contract Processor / Grape Sale) with a contact name field, and a Raise Task flow triggered when grape condition is Poor or botrytis exceeds 30%." },
      { q: "What winery compliance records does the Viticulture module cover?", a: "The Viticulture module includes five winery compliance tabs covering UK licensing, HMRC excise duty, cellar door events, age verification, and wine production records. Licensing — maintain a register of your premises licences and personal licences: licence type, licensing authority, licence reference, issue date, expiry date, Designated Premises Supervisor (DPS) name, and status (Active, Suspended, Expired, or Revoked); a red alert chip flags any licence that has expired. Excise & Duty — log each HMRC excise duty return for wine production: return period, total wine volume (litres), duty rate, duty due (£), submission date, payment status (Draft, Submitted, Paid, or Overdue), HMRC reference, and notes; an Overdue chip appears on any unpaid return past its deadline. Tastings & Tours — record each cellar door or tasting room event: session date, session type (Public Tasting, Trade Tasting, Private Tasting, or Vineyard Tour), number of attendees, ticket or cover price, total session revenue, DPS present flag, operator name, and notes. Age Verification — log every Challenge 25 check carried out during sales and events: check date, operator name, location, outcome (Passed — over 18, Refused — under 18, or Inconclusive), ID type presented, and action taken; the register provides an auditable record of your Challenge 25 policy in practice. Wine Production — record additive use and SO₂ compliance per vintage: vintage year, wine colour, production volume, certified organic status, certifier reference, additive name and type, quantity used, maximum permitted level, actual SO₂ (mg/L), maximum SO₂ permitted (mg/L), and SO₂ compliant flag. The Wine Production tab is shared with the Organic Viticulture module — records appear in both places." },
    ],
  },
  {
    title: "Organic Viticulture",
    icon: Grape,
    color: "bg-purple-50 text-purple-800 border-purple-200",
    items: [
      { q: "What does the Organic Viticulture module cover?", a: "The Organic Viticulture module provides a dedicated compliance workspace for UK organic vineyard certification. It has six organic-specific record types: Block Conversion Register (conversion status, certifying body, and 3-year conversion period tracking per block), Organic Inputs Log (all approved vineyard inputs with approval status and certifier references), Copper Register (running application log with a live progress bar against the 28 kg/ha per 7-year regulatory limit), Input Derogations (Sch. 1 / Annex II case management with correspondence log and expiry tracking), Wine Production Additives (SO₂ compliance and permitted additive records per vintage under UK-retained EU Reg 203/2012 — shared with the standard Viticulture module), and Certificates (organic certificate register with expiry urgency alerts). It also includes all standard Viticulture tabs (Overview, Vine Register, Phenology, Pruning & Canopy, Harvest, Disease Scouting) plus the full set of Winery Compliance tabs shared with standard Viticulture: Licensing, Excise & Duty, Tastings & Tours, and Age Verification (Challenge 25). A dedicated mobile screen for viewing active derogation cases in the vineyard is also included." },
      { q: "How does the 3-year block conversion period work in the Block Conversion Register?", a: "Open Organic Viticulture and go to the Block Conversion tab. Each record represents one vineyard block or group of blocks. Enter the block name, your certifying body (Soil Association, OF&G, etc.), the conversion start date, and the date the block becomes fully organic (3 years from the conversion start, unless your certifier specifies otherwise based on prior land use). The status dropdown shows In Conversion, Fully Organic, Suspended, or Withdrawn. You can also record the pre-conversion land use (e.g. conventional arable or conventional vineyard) and a synthetic input history note — this information is typically requested by certifiers during conversion assessments and annual inspections. UK Organic Regulations 2020 require all conversion documentation to be retained for at least 5 years." },
      { q: "How does the Copper Register track the 28 kg/ha per 7-year limit?", a: "Open Organic Viticulture and go to the Copper Register tab. Each record logs one copper fungicide application: date, product name, copper content percentage, quantity applied, area treated (ha), and the actual copper kg applied. When you add or edit a record, enter the copper kg applied directly — this is the figure you need for your certifier audit (calculate it from the product copper content and application rate per hectare). The register displays a running total of all copper kg applied across all records, shown as a progress bar against the 28 kg/ha per 7-year limit (green up to 70%, amber 70–90%, red above 90%). Your certifier will require this register to be broken down by block and filtered to a rolling 7-year window for inspection — the register provides the raw data you need to produce that report. UK Organic Regulations 2020 implement the cap of 28 kg of copper per hectare applied to the soil over any 7-year period." },
      { q: "How do I manage an input derogation case for a vineyard input?", a: "Open Organic Viticulture and go to the Input Derogations tab. The workflow is split into two stages to keep application evidence and certifier decisions cleanly separated in your audit trail.\n\nStage 1 — New Case: Click New Case and complete the application form: input name (e.g. Copper Hydroxide WP), input type, regulatory basis (e.g. UK Organic Regs 2020, Sch. 1 Part B), certifying body, availability search date and reference number, application date, vintage year, and justification (why the organic equivalent was unavailable). Save — the case is created at Pending status with no decision fields populated.\n\nStage 2 — Record Decision: Once you receive a decision from your certifier, find the case card and click Record Decision →. This opens the decision dialog where you record the decision date, status (Approved, Refused, Withdrawn, or Expired), expiry date (for Approved cases), and any approval conditions. Save the decision — the case card updates to reflect the new status and expiry urgency badge.\n\nEach case shows expiry urgency badges at 90 and 30 days. Expand any case card to view and add correspondence entries — each with date, direction (Inbound/Outbound), type (Email, Letter, Phone Call, Decision Notice, etc.), summary, and reference number. Upload approval letters, availability search evidence, and certifier decisions as document attachments. You are required to complete an availability search and document the result before submitting a derogation application to your certifier." },
      { q: "What are the SO₂ limits for organic wine and how does the Wine Production tab help?", a: "The Wine Production tab is available in both the standard Viticulture module and the Organic Viticulture module — it records the same data in both places and all records are shared. Open either Viticulture or Organic Viticulture and go to the Wine Production tab. UK-retained EU Regulation 203/2012 sets maximum total SO₂ limits for organic wine that are lower than for conventional wine: 100 mg/L for red wine and 150 mg/L for white and rosé wine. Sparkling and sweet wines may have higher permitted levels — check your certifier's guidance for your specific product. For each vintage and wine type, the Wine Production tab lets you record: vintage year, wine colour, production volume in litres, certified organic status and certifier reference, additive name and type (Sulphites / SO₂, Fining Agent, Stabiliser, Acidifier, Preservative, or Other), quantity used and unit, maximum permitted level, actual SO₂ in mg/L, maximum SO₂ permitted in mg/L, and an SO₂ Compliant flag. A compliance chip (Compliant / Exceeds Limit) is shown on each card for quick visual audit checks. The regulatory basis field links each record to the specific retained regulation." },
      { q: "Is there a mobile screen for organic viticulture derogations?", a: "Yes. The mobile app includes a dedicated Organic Viticulture Derogations screen accessible from the Organic overview page via the Vit Derogations quick action button. The screen displays all active and historical input derogation cases with status chips (Pending, Approved, Refused, Expired, Withdrawn) and a summary count row. Tap any case card to expand it and view the full detail: certifier, certifier reference, application date, decision date, expiry date with urgency badge, availability search evidence, justification, approval conditions, and regulatory basis. The screen is read-only — to add correspondence, upload documents, or edit case details, use the dashboard at Organic Viticulture → Input Derogations. Pull down to refresh." },
      { q: "Can I access standard viticulture records from within the Organic Viticulture section?", a: "Yes. The Organic Viticulture page includes all standard Viticulture tabs alongside the organic compliance tabs, so you do not need to navigate between modules. The standard tabs available within Organic Viticulture are: Overview (vineyard block overview and season summary), Vine Register (variety, rootstock, GI classification, and planting records for each vine), Phenology (BBCH growth stage observation log from dormancy through to harvest ripeness), Pruning & Canopy (all canopy operations from winter pruning through to green harvest, including bud counts and pruning weights), Harvest (vintage harvest records with yield per vine, yield per hectare, Brix, pH, titratable acidity, potential alcohol, and botrytis status), and Disease Scouting (pest and disease pressure walkabout log with automatic notifications and mandatory APHA notifiable organism alerts for Xylella fastidiosa and Phytophthora viticola). The full set of Winery Compliance tabs is also shared: Licensing (premises and personal licences), Excise & Duty (HMRC wine duty returns), Tastings & Tours (cellar door event register), Age Verification (Challenge 25 ID check log), and Wine Production (SO₂ and additive compliance records). All improvements made to the standard Viticulture module automatically apply within the Organic Viticulture section as well." },
    ],
  },
  {
    title: "Trade Contacts & Stock",
    icon: Store,
    color: "bg-emerald-50 text-emerald-700 border-emerald-100",
    items: [
      { q: "How do Purchase Order status filter tabs work?", a: "The Purchase Orders list is divided into seven status filter tabs, each showing a live count: All, Outstanding (raised and awaiting delivery), Awaiting Approval (held pending manager sign-off), Draft (saved but not yet submitted), Sent (dispatched to the supplier), Partially Received (some GRNs logged against the order), and Fully Received (all lines receipted). Clicking a tab instantly filters the list to that stage. The counts update in real time as orders move through the workflow — for example, approving an order removes it from the Awaiting Approval count and adds it to Outstanding." },
      { q: "What is the Purchase Order approval workflow?", a: "The approval workflow is triggered automatically when a PO is raised that contains one or more stock catalogue items flagged as requiring manager approval. Rather than going straight to Outstanding, the order is placed into Awaiting Approval status, where it stays until a designated manager reviews it. A Pending Approvals panel appears on the Trade Contacts & Stock page for users with approval rights, listing every order awaiting their sign-off — showing the PO number, supplier, the name of the person who submitted the order, estimated value, and submission date. The approver clicks Approve to move the order to Outstanding (ready to send to the supplier) or Reject to return it to Draft, where the requestor can amend and resubmit. Orders containing no approval-required items proceed directly to Draft or Outstanding as normal." },
      { q: "How do I flag a product as requiring approval before it can be purchased?", a: "Open Trade Contacts & Stock and go to the Product Catalogue tab. Click Add Product or the Edit icon on an existing product. In the product form, toggle the Approval Required switch on. An Approver picker appears — select the farm staff member who must sign off any Purchase Order that includes this product. Save the product. The Approval column in the Product Catalogue table will show a badge and the approver's name for every flagged item. When a PO is raised containing a flagged product — from the dashboard or the mobile app — it is automatically held in Awaiting Approval regardless of any other lines on the order." },
      { q: "What does the Pending Approvals widget show?", a: "The Pending Approvals panel appears on the Trade Contacts & Stock page for managers and users with approval rights, whenever there are orders awaiting their sign-off. For each order it shows the auto-generated PO number (e.g. PO-2025-0014), the supplier name, the Submitted By field showing who raised the order, the estimated order value calculated from the line items, and the date the order was submitted. Approve and Reject buttons are available inline — approving moves the order to Outstanding, rejecting returns it to Draft. The Awaiting Approval tab on the PO list shows the same orders with a live count badge." },
      { q: "What does the 'Submitted By' field on a Purchase Order record?", a: "Every Purchase Order automatically captures the full name of the staff member who raised it in the Submitted By field. This is populated from the logged-in user's name at the moment the PO is created, on both the dashboard and the mobile app — no manual entry is required. The name appears in the Purchase Orders list table, the PO view dialog, and the Pending Approvals widget. On multi-staff farms where procurement spans livestock, arable, and workshop teams, Submitted By provides a clear person-to-order audit trail — which is particularly valuable when a manager needs to query the purpose or urgency of an order awaiting approval." },
      { q: "Can I raise a Purchase Order from the BDE Farm Trac mobile app?", a: "Yes. In the mobile app, open Settings → Trade Contacts & Stock → Raise Purchase Order, or go to the Record tab and tap Raise Purchase Order (visible when the Finance & Business module is active on your farm). The mobile form captures the supplier name, an optional expected delivery date, notes, and one or more line items — each with a product description, quantity, and unit price. An estimated order total is calculated live as you add lines. On submission, the order is created immediately in your farm account. If any line item is associated with an approval-required product, the order is placed into Awaiting Approval automatically. You can also view your full Purchase Orders list from Settings → Trade Contacts & Stock → Purchase Orders, where the same status filter tabs and pending approvals banner are available." },
    ],
  },
  {
    title: "Livestock, Dairy & Animal Health",
    icon: PawPrint,
    color: "bg-amber-50 text-amber-700 border-amber-100",
    items: [
      { q: "How does dairy mobility scoring work in BDE Farm Trac?", a: "Mobility scoring uses the AHDB 0–3 locomotion scale and records individual animals rather than a single herd-level note. In a session, you add one row per animal — entering the ear tag, selecting a score (0 = sound, 1 = imperfect, 2 = lame, 3 = severely lame), and adding any per-animal notes. The session automatically calculates prevalence — the percentage of animals scoring 2 or 3 — and flags sessions that exceed the Red Tractor Dairy threshold. The view dialog shows the full per-animal breakdown, and each session has a printable A4 mobility report. Scorings can also be recorded offline on the mobile app and sync to the dashboard automatically." },
      { q: "How does LIS one-click submission work for sheep, goat and deer movements?", a: "BDE Farm Trac connects to the England Livestock Information Service (LIS) CLA API. Once your LIS Client ID and Client Secret are saved in Settings → Farm Settings → Livestock Integration, a Submit to LIS button appears on every sheep, goat or deer movement row. Clicking it sends the movement data (CPH numbers, ear tag list, movement date, haulier, AML licence) directly to LIS and stores the returned reference number against the record, replacing the LIS Submitted badge. A full submission history — including timestamp, status, reference number, and JSON payload — is accessible by expanding any submitted row. A Beta Sandbox mode lets you test the connection before switching to live submissions." },
      { q: "How does BCMS one-click submission work for cattle movements?", a: "BDE Farm Trac connects to CTS Web Services (British Cattle Movement Service). Enter your CTS credentials in Settings → Farm Settings → Livestock Integration. Once connected, a Submit to BCMS button appears on every cattle movement row. Clicking it submits the movement directly to BCMS and stores the returned reference number against the record. A sandbox mode lets you set up and test without submitting live records to DEFRA. The full submission history with reference numbers, status, and payload log is available by expanding any submitted movement row." },
      { q: "What veterinary records can I record in BDE Farm Trac?", a: "BDE Farm Trac captures a comprehensive veterinary evidence trail. Medicine Records log treatments against named animals with product, dose, batch number, route, withdrawal period, and automatic withdrawal end date calculation. Vet Health Plans record each plan, the vet who prepared it, and track action completion with manager sign-off. The Vet Ledger records vet practice invoices with line-item categorisation (call-out, consultation, medicine, lab test, TB testing, procedure), and reconciles them against logged visits. TB Test Records capture herd-level APHA test records — test type, reactor numbers, clear date — and can be linked directly to the livestock movement records they cleared. Welfare Outcome Assessments record welfare scoring sessions for Red Tractor audit evidence." },
      { q: "How do medicine withdrawal periods work?", a: "Each medicine treatment record includes the product name, batch number, dose, route of administration, withdrawal period in days, and the treated animal's ear tag. BDE Farm Trac calculates the withdrawal end date automatically and surfaces a warning if any animal with an active withdrawal period is recorded as sold or slaughtered. For organic livestock, doubled withdrawal periods (double the standard period) are enforced on all treatments and both end dates — organic milk withdrawal and organic meat withdrawal — are shown on every treatment row in the Organic Livestock module." },
      { q: "How do I record and track fallen stock?", a: "Navigate to Livestock → Mortality Records. Each record uses a four-stage disposal workflow — Reported → Disposal Booked → Collected → Documentation Complete — with stage-action buttons on each record card. Fields cover cause of death, disposal method, fallen stock contractor details (company name, address, phone, vehicle registration, collection reference, collection date and time), veterinary declaration (declaring vet RCVS number and declaration date), invoice information (invoice reference, amount, payment status), and BCMS mortality notification reference. This provides the full contractor and regulatory evidence trail required for Red Tractor mortality and fallen stock audit requirements." },
    ],
  },
  {
    title: "Staff, Labour & PPE",
    icon: ShieldCheck,
    color: "bg-blue-50 text-blue-700 border-blue-100",
    items: [
      { q: "What does the Labour Management module cover?", a: "Labour Management has six tabs: Rota (weekly staff scheduling with department colour-coding and shift assignments), Timesheets (staff submit hours by day and task; managers approve or return for correction; a submission status grid shows who has submitted and who has not across a selected week), Absences (log sickness, annual leave, and other absence types with approval status and days-count), Attendance (actual hours worked vs scheduled, discrepancy flags, and Bradford Factor sickness-absence analysis), Leave Requests (mobile-submitted leave applications with a Pending Approvals panel; approve or decline from the dashboard with SMS notification), and Holiday Planner (month-by-month calendar view with conflict detection across staff leave and shifts)." },
      { q: "How does timesheet submission and approval work?", a: "Staff submit timesheets from their mobile app for each working day — entering hours worked, overtime hours, and a task description. The dashboard shows a Submission Status grid for the selected week, with a colour-coded cell for every staff member showing Not Submitted (grey), Submitted (amber), Approved (green), or Returned (red). Managers click any submitted row to review the timesheet in full, then Approve or Return it with a note. Staff receive an SMS notification when their timesheet is approved or returned. A Labour Cross-Reference report compares timesheet hours against Field Operations records for the same period to identify discrepancies." },
      { q: "How does the PPE module work?", a: "PPE is managed across three registers accessible from Staff & Training → PPE. The Stock Register is a catalogue of all PPE held on the farm — each item records the supplier, product name, EN standard met, quantity in stock, reorder level, and latest purchase invoice reference. The Issue Register records each time PPE is issued to a named staff member — item type, size, issue date, condition at issue, and the staff member's acknowledgement. The Risk Assessments register (under PPE at Work Regulations 2022) records each formal risk assessment — hazard identified, task or area, PPE type required, risk level, specification, assessed by, assessment date, and review date. A PPE Compliance Pack print button generates the full register formatted for assessor inspection." },
      { q: "How do Right to Work checks work?", a: "Navigate to Staff & Training → Staff → [Staff member] → Right to Work. Record the document type checked (passport, biometric residence permit, share code verification, etc.), the document reference number, the date the check was carried out, and the checker's name. An expiry date can be set for time-limited documents (e.g. visa-based work permission) — BDE Farm Trac surfaces an alert when the permission is approaching expiry so the check can be renewed in time. All Right to Work records are retained for two years after the employment ends, in line with Home Office guidance." },
      { q: "What is the Training Competency Matrix?", a: "The Training Competency Matrix (Staff & Training → Competency Matrix) gives a single-page traffic-light view of every staff member against every certificate type held on the farm — PA1, PA2, PA6, forklift, first aid, chainsaw, manual handling, and any custom certificates you have defined. Green cells = valid; amber = expiring within 90 days; red = expired or missing. Clicking any amber or red cell opens the certificate record directly so you can record a renewal. The matrix is printable as an A4 landscape document for staff file audits." },
    ],
  },
  {
    title: "Fields, Crops & Spraying",
    icon: Sprout,
    color: "bg-green-50 text-green-700 border-green-100",
    items: [
      { q: "How do I record a seed drilling event?", a: "Navigate to Field & Crop Management → Seed Drilling and click Add Seed Drilling Record. The form captures drilling date, field (from your registered field list), crop, variety, seed lot number, seed rate (kg/ha), area seeded (ha), treated seed toggle (with treatment product name when dressed — required for BBSRC stewardship compliance), operator, seed cost (£/kg), soil conditions, weather notes, and any additional notes. The seed cost per kg is used by the Season Production Report to calculate total seed input cost and gross margin. Records can be reviewed in a read-only view dialog before editing." },
      { q: "What is an IPM Plan and how does it link to spray records?", a: "The IPM Plan (Sprays & Inputs → IPM Plan) is a written farm-level Integrated Pest Management strategy required by Red Tractor Combinable Crops and Horticulture standards. It is structured in five sections: threshold monitoring approach, action thresholds used (AHDB or farm-specific), non-chemical control measures, spray intervention rationale, and plan review schedule. The plan is version-controlled with author, review dates, and a printable A4 compliance document. Each spray application record includes a Spray Rationale field that links back to the IPM Plan — recording the specific monitoring trigger or threshold evidence that justified the application for a complete monitoring-to-application audit trail." },
      { q: "How does the Season Production Report calculate gross margin?", a: "The Season Production Report (Field & Crop Management → Season Reports) combines all drilling, fertiliser, spray, and harvest records for a selected crop season and field into a single financial summary. Total Seed Cost is calculated from seed cost (£/kg) × seed rate × area across all drilling records. Total Fertiliser Cost comes from the Total Cost (£) field on each NVZ fertiliser application. Total Spray Cost comes from product cost (£/unit) × dose × area across spray records. Revenue is harvest yield (tonnes) × sale price (£/t). Gross Margin = Revenue minus all input costs, also expressed in £/ha. All figures are computed from data already entered — no re-entry is needed." },
      { q: "What is a LERAP assessment and when do I need one?", a: "LERAP stands for Local Environmental Risk Assessments for Pesticides. You need one before applying any Category A or Category B pesticide product within the product's buffer zone of a watercourse. In BDE Farm Trac (Sprays & Inputs → LERAP Assessments), the record captures the CRD Assessment Step (Step 1: notify only; Step 2: full buffer maintained; Step 3: full assessment performed), the standard buffer distance (auto-filled from product label data), crop type and soil type (auto-filled from the field record), assessor name (selected from staff — PA1 and PA2/PA6 required), and an auto-generated LERAP reference number. A Pending Review By field assigns a named farm member who receives an email notification. LERAP records can be created from the dashboard or the mobile app." },
      { q: "How do I track crop rotation and OSR intervals?", a: "The Crop Rotation Planner (Field & Crop Management → Crop Rotation Planner) displays a grid of your fields (rows) against crop years (columns). Each cell shows the crop grown in that field and year, drawn automatically from your harvest and drilling records — no separate data entry required. OSR break interval warnings flag automatically when a field is assigned oilseed rape within three years of a previous OSR crop, highlighting the rotation risk on the grid. The planner also supports manual rotation planning for future seasons by entering planned crops in forward-year cells." },
    ],
  },
  {
    title: "Farm Settings & Invoicing",
    icon: Store,
    color: "bg-slate-50 text-slate-700 border-slate-100",
    items: [
      { q: "How do I add my farm logo and company details to invoices?", a: "Navigate to Settings → Farm Settings. The Invoice & Branding section lets you upload a farm logo (PNG or JPEG, recommended at least 200 × 80 px), enter your registered company name, VAT registration number, Companies House registration number (if applicable), invoicing address, bank name, sort code, account number, and standard payment terms. These details appear on every invoice generated from the Farm Services & Contracting, Workshop, and Livestock trading modules. Changes take effect immediately on all subsequent invoices — previously issued invoices retain the details that were current when they were generated." },
      { q: "Can I have different invoice branding for different farm holdings?", a: "Yes. Each farm holding in a multi-farm account has its own independent invoice branding settings. Switch between farms using the farm selector in the sidebar, then go to Settings → Farm Settings to configure the logo, company details, VAT number, and bank details for that specific holding. This allows group farming businesses or partnerships that trade under different legal entities to produce correctly branded invoices from a single BDE Farm Trac account." },
      { q: "How do I set up multiple farm holdings in one account?", a: "From Settings, click Add Farm Holding to create a new holding. Each holding has its own fields, livestock herds, staff, modules, and compliance records. You switch between holdings using the farm selector at the top of the sidebar. The Group Dashboard (available when two or more holdings are active) shows a consolidated compliance overview across all your holdings — compliance percentages, upcoming expiry alerts, and cross-farm task summaries — so you can manage your whole group from one screen." },
      { q: "How do I invite staff members and manage their access?", a: "Navigate to Staff & Training → Staff and click Add Staff Member. Enter their name, role, department, and email address, then click Send Invite. The staff member receives an email with a link to set their own password. Access level (Manager, Supervisor, or Operator) determines which modules and functions they can view or edit. Managers can approve timesheets, leave requests, and purchase orders. If a staff member leaves, deactivate their account from Settings — this removes their access immediately without deleting any of the records they created, preserving your compliance audit trail." },
    ],
  },
  {
    title: "Account & Billing",
    icon: Landmark,
    color: "bg-violet-50 text-violet-700 border-violet-100",
    items: [
      { q: "How is BDE Farm Trac priced?", a: "BDE Farm Trac uses a per-farm, per-month subscription model. The core platform is included in all subscriptions. You add modules based on your farming operation. Visit the Pricing page for a full interactive cost calculator — add all your farms and select the modules for each." },
      { q: "Can I cancel or change my subscription at any time?", a: "Yes. Subscriptions can be modified — adding or removing modules — or cancelled with 30 days' notice. No long-term contracts are required. Contact the support team to make changes." },
      { q: "Is there a free trial?", a: "Yes. All new accounts receive a 30-day free trial of the full platform with all modules unlocked. No payment details are required to start the trial. Contact the team via the Register Interest page and we will get you set up." },
    ],
  },
];

function AccordionItem({ item }: { item: FaqItem }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="border-b border-border last:border-0">
      <button
        onClick={() => setOpen(o => !o)}
        className="w-full flex items-start justify-between gap-4 py-4 text-left text-sm font-medium text-foreground hover:text-brand transition-colors"
      >
        <span>{item.q}</span>
        <ChevronDown
          className={`w-4 h-4 shrink-0 mt-0.5 transition-transform duration-200 ${open ? "rotate-180" : ""}`}
        />
      </button>
      <div className={`grid transition-[grid-template-rows] duration-200 ease-in-out ${open ? "grid-rows-[1fr]" : "grid-rows-[0fr]"}`}>
        <div className="overflow-hidden">
          <p className="pb-4 text-sm text-muted-foreground leading-relaxed">{item.a}</p>
        </div>
      </div>
    </div>
  );
}

export default function HelpCentre() {
  const [search, setSearch] = useState("");
  const [activeCategory, setActiveCategory] = useState<string | null>(null);

  const filtered = FAQ.map(cat => ({
    ...cat,
    items: cat.items.filter(item =>
      !search || item.q.toLowerCase().includes(search.toLowerCase()) || item.a.toLowerCase().includes(search.toLowerCase())
    ),
  })).filter(cat => {
    if (activeCategory && cat.title !== activeCategory) return false;
    return cat.items.length > 0;
  });

  return (
    <Layout>
      {/* Hero */}
      <div className="relative bg-gradient-to-b from-[#166534]/5 to-transparent border-b border-border">
        <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-16 text-center">
          <div className="inline-flex items-center gap-2 text-xs font-semibold text-green-700 bg-green-50 border border-green-200 px-3 py-1.5 rounded-full mb-4">
            <LifeBuoy className="w-3.5 h-3.5" />Help Centre
          </div>
          <h1 className="text-4xl font-bold text-foreground mb-4">How can we help?</h1>
          <p className="text-lg text-muted-foreground mb-8">Find answers about Red Tractor compliance, organic records, livestock, sprays, and more.</p>
          <div className="relative max-w-xl mx-auto">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-muted-foreground" />
            <input
              type="search"
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Search questions…"
              className="w-full h-12 pl-11 pr-4 rounded-xl border-2 border-border bg-white text-base focus:outline-none focus:border-brand"
            />
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        <div className="flex gap-10">
          {/* Category nav */}
          <aside className="w-52 shrink-0 hidden md:block">
            <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-3">Categories</p>
            <nav className="space-y-1">
              <button
                onClick={() => setActiveCategory(null)}
                className={`w-full text-left text-sm px-3 py-2 rounded-lg transition-colors ${!activeCategory ? "bg-brand text-white font-medium" : "text-foreground/70 hover:bg-secondary"}`}
              >
                All categories
              </button>
              {FAQ.map(cat => (
                <button
                  key={cat.title}
                  onClick={() => setActiveCategory(cat.title === activeCategory ? null : cat.title)}
                  className={`w-full text-left text-sm px-3 py-2 rounded-lg flex items-center gap-2 transition-colors ${activeCategory === cat.title ? "bg-brand text-white font-medium" : "text-foreground/70 hover:bg-secondary"}`}
                >
                  <cat.icon className="w-4 h-4 shrink-0" />
                  {cat.title}
                </button>
              ))}
            </nav>
          </aside>

          {/* FAQ content */}
          <div className="flex-1 min-w-0">
            {filtered.length === 0 ? (
              <div className="text-center py-16">
                <Search className="w-10 h-10 mx-auto mb-3 text-muted-foreground opacity-40" />
                <p className="font-semibold text-foreground">No results found</p>
                <p className="text-sm text-muted-foreground mt-1">Try different search terms or browse all categories.</p>
              </div>
            ) : (
              <div className="space-y-10">
                {filtered.map(cat => (
                  <motion.div
                    key={cat.title}
                    initial={{ opacity: 0, y: 12 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.25 }}
                  >
                    <div className="flex items-center gap-3 mb-4">
                      <div className={`w-9 h-9 rounded-xl border flex items-center justify-center shrink-0 ${cat.color}`}>
                        <cat.icon className="w-4 h-4" />
                      </div>
                      <h2 className="text-lg font-bold text-foreground">{cat.title}</h2>
                    </div>
                    <div className="rounded-xl border border-border bg-white px-5 divide-y divide-border">
                      {cat.items.map((item, i) => <AccordionItem key={i} item={item} />)}
                    </div>
                  </motion.div>
                ))}
              </div>
            )}

            {/* Still need help */}
            <div className="mt-16 rounded-2xl bg-[#166534]/5 border border-[#166534]/20 p-8 text-center">
              <LifeBuoy className="w-10 h-10 mx-auto mb-3 text-[#166534]" />
              <h3 className="text-xl font-bold text-foreground mb-2">Still need help?</h3>
              <p className="text-sm text-muted-foreground mb-6">Our team are farmers and farm business professionals — we understand the compliance pressures you face.</p>
              <div className="flex items-center justify-center gap-6 flex-wrap">
                <a href="/contact" className="inline-flex items-center gap-2 text-sm font-medium text-[#166534] hover:underline underline-offset-2">
                  <Mail className="w-4 h-4" />Send us a message
                </a>
                <a href="tel:+441234567890" className="inline-flex items-center gap-2 text-sm font-medium text-[#166534] hover:underline underline-offset-2">
                  <Phone className="w-4 h-4" />Call the team
                </a>
              </div>
            </div>
          </div>
        </div>
      </div>
    </Layout>
  );
}
